    (7, 4, "ሥራውም ፡ ሁሉ ፡ ለበረከት ፡ ይሆናል ፡ ሕገጋ ቱም ፡ በተድላ ፡ በዶዴስታ ፡ ይፀናሉ።"),
    (7, 5, "አሁንም ፡ ደጋጎች ፡ ሰዎች ፡ ሁሉ ፡ ለአግዚአብ ሔር ፡ ይገዛሉ ፡ ሹህ ፡ ልጆችንም ፡ አስኪ.ወ ዳኝ ፡ ረስ ፡ጾጎነኞዎችን ፡ ይሆናሉ።"),
    (7, 6, "(ፍጹም ፡ ልድ ፡) የሕፃንነታቸውን፡የ ሽምግልናቸውንም፡ወራት፡ ሉ ፡ በተድላ ፡ በደስታ ፡ ይጨርሳሉ።"),
    (8, 1, "ነዚያም ፡ ወራቶች ፡ ምድር ፡ ሁሉ ፡ በውነት ትታረሳለች ፡ በሁለመና ዋም ፡ እንጨቶችን።"),
    (8, 2, "ተክላለች ፡ በረከትንም ፡ ትመላለች።"),
    (8, 3, "ድላ ፡ ደስታ ፡ ያለበቸው ፡ አንጨቶችም ፡ ሉ ፡ በባ. ፡ላይ፡ይተከላሉ ፣ ወሬ6ኖችም፡በባ.፡ ክርስቲያን ሃይማዛ ትና ሥርዓት።"),
    (8, 4, "ር፡8፡ ትም ፡ መሠረይ ፡ አይሆንላቸውም።"),
    (9, 1, "በልጆቻቸው ፡ ደስ ፡ አይላቸውምና ፡ የሚወ ? ቸው ፡ የልጆቻቸውን ፡ ሞት ፡ ያያሉ ፡ በል ቻቸውም ፡ ጥፋት ፡ ሪጨጩ ኸው ፡ ያለቅሳሉ።"),
    (9, 2, "ለዘላለም ፡ ይለምናሉ ፡ ይቅርታም ፡ ፍቅርም ፡ አንድነትም ፡ አይደረግላቸው።"),
    (9, 3, "እኔ ፡ ሄኖክም ፡ ሂ, ፡ አዛዝኤልን ፡ ፍቅር ፡ አን ድነት ፡ አይደረግልህም።"),
    (9, 4, "ሊያጠፋህ ፡ ዕኑፅዕ ፡ መቻያ ፡ በንተ ፡ ታዘዘብህ።"),
    (9, 5, "ግፍን ፣ ስላስተማርህ ፡ የስድብንም ፡ ሥራ ፡ ሁሉ ፡ ስላስተማርህ።"),
    (9, 6, "ለሰው ፡ ልጆች ፡ የኃጢአ ትንና ፡ የግፍን ፡ ነገር ፡ ስላስተማርህ ፡ ዕረፍት ፡ ልመና ፡ ይቅርታ ፡ አይደረግልህም ፡ አልሁት።"),
    (9, 7, "ያን ፡ጊዜ ፡ ሂዩ ፡ ለሁሉም ፡ አንድነት ፡ ነገርኋ ቸው።"),
    (9, 8, "አነሱም ፡ ሁሉ ፡ ፈሩ ፡ ፍራት ፡ መንቀጥቀጥም ፡ ያዛቸው።"),
    (
        9,
        9,
        "ልጽፍላቸው ፡ ለነሱም ፡ የኃጢአታቸው ፡ መስ ተሥረያ ፡ ሊሆናቸው ፡ በሰማይ ፡ ወዳለ ፡ ወደ አግዚአብሔርም ፡ የልመናቸውን ፡ መታሰቢያ እኔ ፡ እንዳሳርግላቸው ፡ የልመናቸውን ፡ መታ ሰቢያ ፡ ጳፍልን ፡ ብለው ፡ ለመኑኝ።",
    ),
    (
        9,
        10,
        "እነሱ ፡ ከዛሬ ፡ጀምረው “ከአግዚአብሔር ፡ ጋራ፡ መነጋገር ፡ አይችሉምና ፡ ከተፈረደበቸው ፡ በደል ፡ ኃፍረት ፣ የተነሣ ፡ ዓይናቸውን ፡ ወደ ፡ ሰማይ ፣ ቀና ፡ አድርገው ፡ ለማየት ፡ አይችሉ ምና።",
    ),
    (
        9,
        11,
        "የዚያን ፡ ጊዜ ፡ ስለ ፡ ሰውነታቸው ፡ የፍጹም ፡ ልመናቸውን ፡ መታሰቢያ ፡ ጻፍሁ ፡ የኃጢአታ ቸው ፡ መስተሥረያ ፡ የዘመንም ፡ ርዝመት ፡ ይሆንላቸው ፡ ዘንድ ፡ ስለ ፡ ለመኑኝ ፡ ያንዱ ንም ፡ ያንዱንም ፡ ሥራቸውን ፡ ጻፍኩ።",
    ),
    (10, 1, "ሂጀም ፡ በውሀዎች ፡ ዳር ፡ ተቀመጥሁ ፡ ይቹ ውም ፡ በአርሞንሌም ፡ ግራ ፡ ቀኝ ፡ ያለች ፡ አገር፡ናት።"),
    (10, 2, ") አስክካንጎላች ፡ ድረስ ፡ የልመናቸውን ፡ መታሰ ቢያ ፡ ተናገርሁ።"),
    (
        10,
        3,
        ") ) እነሆ ፡ ሕልም ፡ መጣብኝ ፡ ራዕዮ ትም ፡ ተገለ ሇጡልኝ L! ) h በሰማያዊ ፡ ማዕርግ ፡ ለነበሩ ፡ ለደቂቀ ፡ ሴት ፡ ነግሬ ፡ አሰድባበቸው ፡ ዘንድ ፡ መቅሠፍት ፡ ያለ በት ፡ ራዕይን ፡ አየሁ።",
    ),
    (
        10,
        4,
        "ነቅቹም ፡ ወደነሱ ፡ መጣሁ ፣ በሲሂሊርና ፡ በሊ በኖስ ፡ መክከል ፡ በለች ፡ በዑብልስያኢል ፡ ፊታቸውን ፡ ተከናንበው ፡ ሁሉም ፡ አያለቀቡ፡ ተሰብስበው ፡ ተቀምጠው ፡ ነበር።",
    ),
    (10, 5, "እኔም ፡ ተኝቼ ፡ ያየሁትን ፡ ራአይ ፡ ሁሉ ፡ በፊታ ቸው ፡ ተናገርኩ።"),
    (
        10,
        6,
        "እውነት ፡ ነገር ፡ ያለበት ፡ይሀነን ፡ ቃል ፡ እናገር ዘንድ ፡ በደብር ፡ ቅዱስም ፡ ለነበሩ ፡ ለኃጢአ ታቸው ፡ ለሚተጉ ፡ ለደቂቀ ፡ ሴትም ፡ አስተ ምር ፡ ዘንድ ፣ ጀመርሁ።",
    ),
    (10, 7, "የከበረ ፡ የገነነ ፡ ፈጣሪ ፡ በዚያች ፡ ራዕይ ፡ ንገ ራቸው ፡ ብሎ ፡ አንዳዛክ ፡ ከጥንት ፡ ጀምሮ።"),
    (10, 8, "990 ክርስቲያን ሃይማዛ ተና ሥርዓት hኖክ።"),
    (10, 9, "z በቀጽሩም ፡ ዙሪያ ፡የሚነፎ፡ አላት ፡ አለ ፡ ደጃ ፉም ፡ በአሳት ፡ ይቃጠላል።"),
    (10, 10, "ወደዚያም ፡ ቤት ፡ ውስጥ ፡ ገበሆሁ ፡ አሳት ፡ አንደ፡ መሆኑ ፡ ይኮ ቃል ፡ በረድ ፡እንደ፡ መሆኑ ፡ ይቀ ዘቀዛል።"),
    (
        10,
        11,
        "ምንም ፡ ምንም ፡ ተድላ ፡ ደስታ ፡ ሕይወት ፡ በውስጡ ፡ የለም ፡ ፍራት ፡ ሸፈነኝ ፡ አንቅጥቅ ጥም ፡ ያዘኝ ፡ ታውኬ ፡ እየተንቀጠቀጥሁ ፡ በግ ምበሬ ፡ ወደቀሁ ፡ በሕልሜም ፡ አንዲህ ፡ ያለ፡ ራዕይ ፡እየሁ።",
    ),
    (10, 12, "ከዚህ ፡ ቤትም ፡ የሚበልጥ ፡ ሴላ ፡ ቤት ፡አነሆ፡ ለ።"),
    (10, 13, "በፊቴም ፡ ደጃፉ ፡ ሁሉ ፡ የተከፈተ ፡ ነው ፡ በአ ት ፡ ቅጽርም ፡ የተሠራ ፡ ነው።"),
    (
        10,
        14,
        "በሁሉም ፡ ይበልጣል ፡ በስብሐት ፣ በብርሃን በክብርም ፡ በወርድም ፡ በቁመትም ፣ የብርሃ ኑም ፡ ነገር ፡ የወርዱም ፡ የቁመቱም ፡ ነገር፡ ለናንተ ፡ መናገር ፡ የማይቻለኝ ፡ እስከሆን ፡ ድረስ ፡ በሁሉ ፡ ይበልጣል።",
    ),
    (10, 15, "ወልወሉያ ፡ አሳት ፡ ነው ፡ በላዩም ፡ መብረቅ ፡።"),
    (10, 16, "የኮከቦች ፡ መሮጫ ፡ አለበት ፡ ጠፈሩም ፡ የሚ ድ ፡ አሳት ፡ ነው።"),
    (10, 17, "(አንደ ፡ ቀለም ፡ ሳጋ፡) በውስጡም ፡ ከፍ ፡ ያለ ፡ የአግዚአብሔርን ፋን ፡ ፈጽሜ ፡ አየሁ።"),
    (10, 18, "መልኩም ፡ ኣንደ ፡ ውርጭ ፡ ነው ፡ አጎበሩም፡ እንዶሚያበራ ፡ ፀሐይ ፡ ነው ፡ የከ.ሩቤልም ፡ ቃል ፡ ይሰማል።"),
    (10, 19, "ከታላቁ ፡ ዙፋንም ፡ በታች ፡ የሚነድ ፡ የአሳት ሳሾች ፡ ይወጣሉ ፡ ፊቱንም ፡ ማየት ፡ አይቻ ላቸውም።"),
    (10, 20, "ክብር ፡ በለቤት ፡ ጌታም ፡ በሱ ፡ ላይ ፡ ተቀም .ል ፡ መገጐናጸፊያውም ፡ ከፀሐይ ፡ ይልቅ ፡ በራል ፡ ከበረድም ፡ ሁሉ ፡ ይነጣል።"),
    (
        10,
        21,
        'ከመላእክት ፡ ማንም ፡ ማን ፡ አሱ ፡ ወዳለበት ፡ ሣግበት ፡ አይችልም ፡ የከበረ ፡ የተመሰገነ ፡ ቱንም ፡ ማየት ፡ አይችል ፡ ከሥጋቁ ፡ ከደ ቱ ፡ ሰው ፣፡ ያንን ፡ አሳት ፡ ያይ ፡ ዘንድ ፡ ማየት የሚቻለው ፣፡ ጓነወ = በዙሪያውም ፡የ"ሂነድ ፡ አሳት ፡ አለ ፣ በፊቱም ላቅ ፡ አሳት ፡ ቁል።',
    ),
    (10, 22, "(ደደ ፡ ጠሂ መልእክ ው ፡) በዙሪያው ፡ ክሉ ፡ መላአክትም ፣ ወደሱ ፡ የሚ ርብ ፡ የለም ፡ የብዙ ፡ ብዘ ፡ መላእክትም ፡ ፊቱ ፡ አሉ።"),
    (11, 1, "ሱ ፡ ግን ፡ ከባሕርዩ ፡የተለየ ት ፡ምክርን ፡ አይ ወደም።"),
    (11, 2, "ደሱ ፡ የሚቀርቡ ፡ መላአክትም ፡ በቀንም በሌሊትም ፡ ከሱ ፡ ፈጽመው ፡ አይርቁም።"),
    (
        12,
        1,
        "ኔም ፡ አስከዚህ ፡ ድረስ ፡ እየተንቀጠቀጥሁ ቴን ፡ ተከናንቤ ፡ ነበርኩ = ታም ፡ ባንደበቱ ፡ ጠርቱቶ ፡ ሄሩክ ፡ ወዶዚህ፡ ረብ ፡ ለከበረ ፡ ቃሌም ፣ ታዘዝ ፡ አለኝ።",
    ),
    (12, 2, "አንሥቶም ፡ አስክ ፡ ደጃፉ ፡ ድረስ ፡ አቀረበኝ።"),
    (12, 3, "48፡ ተ ክርስቲያን ሃይማ ትኝ ሥርዓት የተወለዱ ፡ በምድር ፡የሚኖሩ ፡ ሰዎችም ፡ ማደ ሪያቸው ፡ በምድር ፡ ይሆናል።"),
    (12, 4, "ከደመና ፡ የሚደርሱ ፡ ረጃጅሞች ፡ ሰዎችም ፈጽመው ፡ ይጠፋሉ ፡ አስበሳቸውም ፡ ይጣላሉ በቫሀ ፡ ዓለም ፡ ሰበውን ፡ ያጠፋሉ።"),
    (12, 5, "በሰውም ፡ ኃዘንን ፡ ያደርጋሉ ፡ አነሰቸውም ፡ የሚበሉትን ፡ አህል ፡ ምንምን ፡ አያገኙም።"),
    (12, 6, "ማዩ ፡ አይህን ፡ ይሠጨልጣሉ ፡ እንጂ ፡ አይጠ ሙም ፡ በመኖርም ፡ አይታወቁም።"),
    (13, 1, "ጥፋትና ፡ በሰልፍ ፡ በታዘዘበት ፡ ወራት ፡ ተወል ደዋልና ፡ አነዚህ ፡ ሰዎች ፡ ኑረው ፡ በሴቶችና በወንዶች ፡ ላይ ፡ በጠላትነት ፡ አይነሱም ፡ አለ።"),
    (
        13,
        2,
        "ወገኖቻቸው ፡ ከሚሆኑ ፡ ከደቂቀ ፡ ሴት ፡ የተወለዱ ፡ የረዓይት ፡ ሞታቸው ፡ በወጡበት ፡ በቦታ ፡ ዓው = ሞታቸውም ፡ ሙሉን ፡ ሞት ፡ ይሁን = ፍርድ ፡ ሳይደረግ ፡ የመከራ ፡ ፍጻሜ ፡ አስከሚ ይደረግባት ፣ እስክ ፡ ዕለተ ፡ ምጽአት ፡ ድረስ እንደዚሁ ፡ ይስፋፉሉ ፡ የከበረ ፡ መንግሥተ ፡ ሰማይ ፡ ከመሰጠቱ ፡ አስቀድሞ ፡ ሕግን ፡ በዘ ነኑ ፡ ሰዎችና ፡ በደቂቀ ፡ ሴት ፡ ፍርድ ፡ ይጀመ ራል።",
    ),
    (13, 3, "አሁንም ፡ ለነሱ ፡ ልትለምንላቸው ፡ የላኩህን ፡ ከዚያ ፡ አስቀድሞ ፡ በደብር ፡ ቅዱስ ፡ የነበሩ ለ»ኃጢእት ፡ የሚተጉ ፣ ደቂቁ ፣ ሴትን ፡ አንዲህ በላቸው።"),
    (13, 4, "| ዛሬም ፡ በደብር ፡ ቅዱስ ፡ ነበራችሁ ፡ የተሠወ ሩም ፡ ኃጢአቶች ፡ ገና ፡ አልተገለጡላችሁም ፡ ነበር።"),
    (13, 5, "የተናቀ ፡ ምሥጢርንም ፡ አወቃችሁ ፡ በልቡ ናችሁም ፡ ዕናት ፡ ይህነን ፡ ነገር ፡ ለሴቶች ፡ ነገ ራችሁ።"),
    (13, 6, "ከዚሀም ፡ ምሥጢር ፣ በወንዶችና ፡ በሴቶች ፡ በዚህ ፡ ዓለም ፡ ክፋትን ፡ ያበዛሉ ፡ አንግዲህስ፡ ፍቅር ፡ አንድነት ፡ የላችሁም ፡ በላቸው ፡ አለኝ።"),
    (
        13,
        7,
        "እንደ ፡ ቋያ ፡ የሚቃጠሉ ፡ ሰዎች ፡ ወዳሉበት ፡ ወደዚያ ፡ ወደ ፡ አንድ ፡ በታ ፡ መላአክት ፡ ወሰ ዱኝ ፡ ሊታዩም፡ በወደዱ ፡ ጊዜ ፡ ሰው ፡ ሆነው ፡ ይታያሉ።",
    ),
    (13, 8, "ጥቁዋቀል ፡ ነፉስ ፡ ወዳለበት ፡ቦታ ፡ ራሱም ፡ አስከ ሰማይ ፡ ወደሚደርስ ፡ ተራራ ፡ ወሰዱኝ።"),
    (
        13,
        9,
        "(ስነ፣ ፍጥረት ፡) የሚያበሩ ፡ አራት ፡ ቦታዎችን ፡ አየሁ ፡ በጥል ቁም ፡ዳርቻ ፡ ነጐድጓድ ፡ አለ ፡ የአሳት ፡ ቀስት ፡ የአሳት ፡ ፍላፃ ፡ ጐረጐሪያቸውም ፡ የአሳት ፡ ሰይፍ ፡ መብረቁችም ፡ ሁሉ ፡ አሉ።",
    ),
    (13, 10, "የሚናገር ፡ የመጣያ ፡ ወሀ ፡ አስከ ፡ አለበት ፡ ድረስ ፡የምዕፅራብም ፡ አሳት ፡ እስካለበት ፡ ድረስ ወሰዱኝ ፡ ይኸውም ፡ የፀሐይን ፡ መግቢያ።"),
    (14, 1, "ሁሉ ፣ የሚይዝ ነው።"),
    (
        14,
        2,
        "አሳቱ ፡ አንደ ፡ ወሀ ፡ አስከሚፈስ ፡ አስከ ፡ አሳት ፈሳሽ ፡ ድረስ ፡ መጣሁ ፡ በምዕራብ ፡ ወዳለ ፡ 993 [ Si toe Ly) by bi ተ ክርስቲያን ሃይማነ ትና ሥርዓት ጥክ።",
    ),
    (14, 3, "ደ፡ጻ፡ በዚያም ፡ በገሃነም ፡ ላይ ፡ ቦታ ፡ አየሁ ፡ ለዚ ያም ፡ ቦታ ፡ በላይ ፡ ጠፈር ፡ በታችም ፡ መሠ ረት ፡ የለውም።"),
    (14, 4, "የምድረ ፡ በዳ ፡ ቦታ ፡ ነው ፡ አንጂ ፡ በላዩ ፡ ውሀ ፡ የለም ፡ ወፎችም ፡ የሉም።"),
    (14, 5, "በዘያም ፡ የሚያስፈራ ፡ ቦታን ፡ አየሁ ፡ አንዶ ሚቃጠሉ ፡ እንደ ፡ ታላላቅ ፡ ተራሮች ፡የሚቃ ጠሉ ፡ ሰበት ፡ ኮከቦችንም ፡ አየሁ።"),
    (14, 6, "የሚጠይቀኝ ፡ ረቂቅ ፡ ባልደረበዬም ፡ እንደመ ሆኑ ፡ መልእጸኩ ፡ ይሀ ፡ ቦታ ፡ የምድርና ፡ የሰ ማይ ፡ መሬዜረኻ ፡ ቦታ ፡ነው።"),
    (14, 7, "ለሰማይ ፡ ኮከቦች ፡ ለደቁቀቁ ፡ ሴት ፡ ለሰማይም ፡ ሠራዊት ፡ በአሳት ፡ ላይ ፡ ለሚገለበበጡ ፡ ኮከበ ችም ፡ ይሀ ፡ የግዞት ፡ ቤት ፡ ሆናቸው ፡ አለኝ።"),
    (14, 8, "በጊዚያቸው ፡ አልመጡምና ፡ በአአምሮ ፍጹም ፡ ከመሆናቸው ፡ አስቀፉቁ ፡ የእግዚአ ብሔርን ፡ ትአዛዝ ፡ ያፈረሱ ፡ አደህ ፡ ናቸው።"),
    (14, 9, "የተሠወረ ፡ፍዳቸውን፡ በሚቀበሉበት ፡ዘመን፡ እስክ ፡ ኃጢአታቸው ፡ መጨረሻ ፡1ጊዜ፡፡ ድረስ፣ ተቁጥቶ ፡ ጸጋዛቸው።"),
    (14, 10, "ሁርኤልም ፡ በዚህ ፡ በነገሩ ፡ ደቂቀ ፣ ሴት ፣ ከሴ ቶች ፡ ጋራ ፡ አንድ ፡ ሆነው ፡ ሰውነቶቻቸው ፡ በፍዳ ፣ ተይዘው ፡ ይናራሉ።"),
    (
        14,
        11,
        'በብዙ ፡ ወገንም ፡ አብነት ፡ ሁነዋቸው ፡ ሰዎችን ፡ አረክከቧ.ቸው ፡ ታላቅ ፡ በሆነ ፡ ጨርሰው ፣ ኣስኪ. ያጠፋቸው ፡ ድረስ ፡ በሚፈረድፍበቸው ፡ ገንዘብ" ጽኑ ፡ ፍርድ ፡ በሚፈረድበት ፡ በዕለተ ፡ ምጽ አት ፡ ይፈረድጽበቸዋልና ፡ ምዕመናን ፡ ለሥላሴ እንዲሠዉ ፡ አነሱም ፡ ለአጋንንት ፡ ይሠዉ ፡ ዘንድ ፡ ሰዎችን ፡ ያስቷቸዋል።',
    ),
    (14, 12, "ሚስቶቻቸውም ፡ ከፍ ፡ ባለ ፡ ማዕርግ ፡ የነበሩ የሴትን ፡ ልጆች ፡ አስተው ፡ ደግና ፡ ሴቶችን ፡ ይሆናሉ።"),
    (14, 13, "( ይመስላሉ ፡ለሊ.፡ነ ፡) አኔ ፡ ሄኖክ ፡ በሁሉ ፡ ዳርቻ ፡ በአድማስ ፡ ሁ ፡ የኔን ፡ ብቻ ፡ ሥራ ፡ አየሁ ፡ ከሰዎችም ፡ አኔ።"),
    (14, 14, "እንዳየሁ ፡ ያየ ፡ የለም።"),
    (14, 15, "ለምስጋና ፡ የሚተጉ ፡ የከበሩ ፡ የመላአክት ፡ ስማቸው ፡ ይህ ፡ ነው።"),
    (14, 16, "ከከበሩ ፡ ከመላእክት ፡ አንዱ ፡ ሁርኤል ፡ በመ ብረቅ ፡ በነጐድጓድ ፡ የተሾመ፡ነው።"),
    (14, 17, "በሰው ፡ ቀ*ስል ፡ የተሾመ ፡ ከከበሩ ፡ ከመላ ክት ፡ አንዱ ፡ ፍፋኤል ፡ ነው።"),
    (14, 18, "ዲያብሎስን ፡ የሚበቀለው፡ አጋንንትንም የሚ በቀላቸው ፡ ከከበሩ ፡ ከመላአክት ፡አንዱ ፡ራጉ.. ኤል ‘ነው።"),
    (14, 19, "ለሰው ፡ በደረገው ፡ በጎነት ፡ ላይ ፡ ለሕዝቡ ፡ ታዛ ፡ ነውና ፡ ከክበሩ ፡ ከመላእክት ፡ አንዱ ሚካኤል ፡ ነው።"),
    (
        14,
        20,
        "አእምሯቸውን ፡ በጡ ፡ ሰዎችም ፡ ላይ ፡ የተ ሾመ ፡ ከከበሩ ፡ ከመላእክት ፡ አንዱ ፡ ሠረቃ ኤል ነው = በባቦች ፡ ላይ ፡ በገነትም ፡ በሉ ፣ ጻድቃን ፡ ላይ፡ BEF Ly Akt agi aft ag igs #፤ ai ft aE 1%; 7 ቕ፤ ተ ክርስቲያን ሃይማካነ ትና ሥርነት ቱና ክ።",
    ),
    (
        14,
        21,
        "ዩ፡ እሂህ ፡ መልክም ፡ መልክም ፡ በታዎች ፡ የሞቱ ሰዎች ፡ ነፍሶች ፡ በነሱ ፡ ሊሰበሰቡባቸው ፡ አነ ዚህ ፣ ለነሱ ፡ ተፈጠሩላቸው ፡ መላእክትም ፡ የደጋግ ፡ ሰዎች ፡ ልጆች ፡ ነፍሶችን ፡ ሁሉ በዚያ ፡ ይሰበስባሉ።",
    ),
    (14, 22, "ጸም ፡ መቻያቸውን፡አስተሚቀበሉበት፡ቀን፡ ድረስ ፡ አስክ ፡ ጊዚያቸውም ፡ ቀን ፡ ድረስ ፡ እነ ሱን ፡ የሚያኖናሩበቸው ፡ እነዚህን ፡ በታዎች፡ ሥላሴ ፡ ፈጠሩ።"),
    (
        14,
        23,
        "ይኸውም ፡ በነሱ ፡ ታላቅ ፡ መክራ ፡ አስኪደረንግ በቸው ፡ ድረስ ፡ ብዙ ፡ ዘመን ፡ ነወ የደጋግ ፡ ሰዎች ፡ ልጆች ፡ ነፍዕችንም ፡ አየሁ፡ እነሱ ፡ ሙተው ፡ ሳሉ ፡ ቃላቸው ፡ አስከ ፡ ሰማይ ፡ ይደርሳል ፡ ወንድሞቻቸውንም ፡ ይከሳሉ ፡ ይጣ ሳሉ።",
    ),
    (
        14,
        24,
        "ያን ፡ ጊዜም ፡ ከኔ ፣ ጋራ ፡ ያለ ፡ ሩፋኤል ፡ ቃሉ፡ አስከ ፡ ሰማይ ፣ ድረስ ፡ የሚደርስ ፡ የሚከስ ፡ ይኽ ፡ ነፍስ ፡ የማነው ፡ ነፍስ ፡ ብዬ ፡ ጠየቅሁት።",
    ),
    (
        14,
        25,
        "ይህ ፡ ነፍስ ፡ ወንድሙ ፡ ቃየል ፡ በግፍ ፡ ከገደ ለው ፡ ከአቤል ፡ የተለዩ ፡ ነፍስ ፡ ነው ፡ ልጁ ፡ ከዚህ ፡ ዓለም ፡ አስኪጠፋ ፡ ድረስ ፣ የልጅ ልጁም ፡ ከሰው ፡ ልጅ ፡ ተለይቶ ፡ አስኪጠፋ ፡ ቃየልን ፡ ይከሳል ፡ ብሎ ፡ መለሰልኝ።",
    ),
    (15, 1, "ያን ፡ ጊዜም ፡የጻድቃንን ፡ ነገር ፡የኃጥዋአንንም፡ ነገር ፡ ሁሉ ፡ ጠየቅሁ ፡ አንዱ ፡ ክንዱ. ፡ ስለምን ተለየ ፡ አልኩ።"),
    (
        15,
        2,
        "የሞቱ ፡ ሰዎችን ፡ ነፍስ ፡ ይለዩ ፡ዘንድ ፡ እነዚህ ሦስት ፡ በታዎች፡ ተፈጠሩ ፡የጻድቃንም ፡ነፍስ፡ አንደዚህ ፡ ተለዩ ፡ ብሎ ፡ መለሰልኝ ፡ይህ፡ቦታ፡ ብርሃን ፡ ያለበት ፡ የውህ ፡ ምንጭ ፡ ነው።",
    ),
    (
        15,
        3,
        "አሁን ፡ አንደ ፡ ተገናርሁት ፡ ለጻድቃን ፡ ቦታ እንደ፡ ተፈጠረ፡ በዚህ ፡ዓለም ፡ ሞተው ፡በተቀ በሩ ፡ ጊዚ ፡ለ.ኖሩበት ፡ ለኃጥአን ፡በታ ፡ አንደዶ፡ ተፈጠረላቸው በሕይወተ ፡ ሥጋ ፡ ሳሉ ፡ በነሱ ፡ መከራ ፡ አል ተደረገበቸውም።",
    ),
    (
        15,
        4,
        "መቻያ ፡ አስከሚቀበሉበት ፡ እስከ ፡ ዕለተ ፡ ምጽ ዓት ፡ ድረስ ፡ በዚች ፡ ታላቅ ፡ ጭንቅ ፡ ተይዘው፡ ሊኖሩ ፡ በዚያ ፡ ቦታ ፡ነፍሰቻቸው ፡ ከጻድቃን ፡ ነፍሳት ፡ ይለያሉ ፡ ለሚሳዶቡም ፡ ሰዎች ፡ አስክ ዘላለሙ ፥ ድረስ ፣ መከራና ፡ መቅሠፍት ፡ ይደረ ጉበቸዋል ፡ በሰበውነታቸውም ፡ በቀል ፡ ትደረግ በቸዋለች።",
    ),
    (
        15,
        5,
        "በዚያ ፡ ቦታ ፡ አስከ ፡ ዘላለሙ ፡ ዓሥሮ ፡ ያግዛቹ ዋል ፤ ምንም ፡ ከዕለተ ፡ ምጽዓት ፡ አስቀድሞ ፡ ቢሆን ፣ በዚያ ፡ አስክ ፡ ዘላለም ፡ ድረስ፡ ዓሥሮ፡ ያግዛቸዋል።",
    ),
    (
        15,
        6,
        "የኃጥአን ፡ ነፍስ ፡ ቦታ ፡ አንደ ፡ ተለየ ፡ ወንድ ሞቻቸውን ፡ ለሚክሰሱ ፡ በኃጥአንም፡ ወራት ፡ በሞቱ ፡ ጊዜ ፡ የጥፋታቸውን ፡ ነገር ፡ ለአግዚልአ ብሔር ፡ ለሚያሳዩ ፣ ለጻድቃንም ፡ ነፍስ ፡ ቦታ።",
    ),
    (15, 7, "ለጻድቃንም ፡ ነፍስ ፡ ቦታ ፡ አንደ ፡ ተፈጠረ ፡ በደልን ፡ የጨረሱ ፣ ኃጥአንን ፡ ሆኑ ፡ አንጂ ፡ i=; iw ተ ክርስቲያን ሃይማዛ፥ ትና ሥርዓት።"),
    (15, 8, "፡i፡ ቁጠሉ፡ ጽፍቁ፣ነው ፡ ፍሬው ፡ ንብብር ፡ ለሊያ ውትም ፡ ፈጽቱ ፡ የተወደደ ፡ ነው ፡ ልጸልሁ።"),
    (15, 9, "የዘ.ያን ፡ ጊዜ ፡ ከኔ ፡ ጋራ ፡ የለ ' በላያቸው ፡ 12: የተመ ፡ ፈጽመው ፡ ከከበሩ ፡ ከመላአክት አንዱ ፡ ሚካኤል ፡ መለሰልኝ።"),
    (15, 10, "ሄኖክ ፡ የዚህን ፡ አንጨት ፡ ሽታ ፡ ነገር፡ ምን፡ ፲፫፡ ትጠሮቃለህ ፡ ልታውቅስ ፡ ምን ፣ ትመረምረ ለህ ፡ አለኝ።"),
    (
        15,
        11,
        "ያን ፡ ጊዜም ፡ ክኔ ፣ ኔኖክ ፡ አንዲህ ፡ ብዬ ፡ መለ ፲8፡ ስሁለት ፡ የእንሪሠቶችን ፡ ሁሉ ፡ ነገር ፡ ላውቅ ፡ አወዳለሁ ፡ ይልቁንም ፣ የዚህን ፡ አንጨት ፡ ነገር ፡ ላውቁ ፡ እወዳለሁ ፡ አልሁት።",
    ),
    (
        15,
        12,
        "አሱም ፡ አንዲህ ፡ ብሎ ፡ መለሰልኝ ፡ ረጅም ሆኖ ፡ የምታየው ፡ ራሱ ፡ የጌታን ፡ መቀመጫ ፡ መስሉ ፡ ያየሽው ፡ ይህ ፡ ተራራ ፡ የተመሰገነ ፡ የገነነ ፡ የዘለዓለም ፡ ንገሥ ፡ የሚሆን ፡ የክብር በለቤት ፡ ሬሀችን ፡ ዓለም ፡ በበጎ ፡ ሊጎበኛት ፡ በወረደ ፡ ጊዚ. ፡ የሚቀመጥበት ፡ 1ዙፋኑ ፡ ዴብረ፡ ሲና ፡ነው።",
    ),
    (
        16,
        1,
        "ይሀም ፡ መዓዛ ፡ የለው ፡ የተወደደ ፡ አንጨት ፡ ፤8፣ ጌታ ፡ ሁሉን ፣ በተቀበለ ፡ ጊዜ ፡ አስከ ፡ ዘለዓ ለም ፡ የሚሆን ፣ መከራም ፡ በተፈጸመ ፡ ጊዜ ፡ ጽኑ ፡ መከራ ፡ እስከሚደረግበት ፡ ቀን ፣ ድረስ ፡ ከሥጋዊ ፡ ከደማዊ ፡ አንስ ፡ ስንኳ ፡ ሊነከው ፡ ሥልጣን ፡ የለውም።",
    ),
    (16, 2, "ለደጋጎች ፡ ለተቁዋረትም ፡ ሰዎች ፡ ከዚህ ፡ አን i፮።"),
    (16, 3, "ጨት፡ፍሬ፡ ይሰጣቸዋል፡ለተመረጡም፡ሰዎች፡ ደኅንነት ፣ ይሰጣል።"),
    (16, 4, "የዘለዓለም ፡ ንጉሥ ፡ ወደሚሆን ፡ በደጊቱ ፡ i፳፣ ማደሪያ ፡ አንጻር ፡ በመስዕ ፡ በኩል ፡ በከበረ ፡ በታ ፡ ይተከላል።"),
    (17, 1, "ei yy est ያን ፡ ጊዜም ፡ ፈጽመው ፡ ዶስ ፣ ይላቸዋል።"),
    (
        17,
        2,
        "[U) በየወገናቸው ፡ ወደ ፡ ከበረ ፡ በታ ፣ ሽቱን ፡ ያቀ 20: ርዙለታል ፡ አባቶችህ ፡ ብዙ ፡ ዘመን ፣ አንደኖሩ፡ አነሱም ፡ በዚ.ህም ፡ ዓለም ፡ ብዙ ፡ ዘመን ፣ ይና ራሉ።",
    ),
    (17, 3, "በዘመናቸውም ፡ መከራና ፡ አዘን ፡ መቅሠፍ ዕ፣ ትና ፣ ድክምም ፡ አይዳ ስላቸው ፡ (አያገኛቹቸ ወም)።"),
    (
        17,
        4,
        "አንደዚህ ፡ አድርጎ ፡ ወዳጆቹ ፡ ለሆኑት ፡ ሰዎች፡ ፳ጽ፪፣ አዘጋዙቷልና ፡ አንደዚህ ፡ አድርጎ ፡ ፈጥሮ ይስጠ.ቸው ፡ ብሏልና ፡ የዘላለም ፡ ንገሥ፡ የሚ ሆን ፡ የክብር ፡ ባለቤት ፣ ጌታን ፣ አመሰገንሁት ፡ ኣለ።",
    ),
    (
        17,
        5,
        "ከዚያ ፡ ተነሥቹ ፡ ወደ ፡ ምር ፡ መከከል ፡ ጽር ሄድሁ ፡ የከበረ ፡ የለመለመ ፡ አንጨት ፡ የተ ቈረጠ ፡ ለምለሞ ፡ የሚኖር ፡ ጫፍ ፡ ያለበት ፡ ቦታንም ፡ አየሁ።",
    ),
    (17, 6, "(ከነቢያት ፡ የተወለዱ ፡ ሐዋ ርያት ፡ ናቸው።"),
    (17, 7, ") በዚያም ፡ ቦታ ፡ የከበረ ፡ ተራራን ፣ አየሁ ፡ በተ ጽ8፣ ራራውም፡ በታች ፡ በምሥራቁ አንጻር፣ውህ፣ አለ ፡ የሚፈሰውም ፡ ወደ ፡ ሰሜን ፡ነው።"),
    (17, 8, "(ትእ ምርት ፡ነው።"),
    (18, 1, ") በምሥራቅም ፡ በዙል ፡ ከዚህ ፡ የሚበልጥ ፡ ፳፪! ተ ክርስቲያን ሃይማዛ ትና ሥርንት ክ።"),
    (18, 2, "፣ ፍሬ ፡ የተገኙ ነገር ፥ ግን ፡ ከዚህ ፡ አንሪኳት እንጨቶችን ፡ ተመልቷል።"),
    (18, 3, "ውሀም ፡ ከወደላይ ፡ ይመነጫል ፡ ቫዛቱውም ፡ በገ፣ቶ ፡ ይታያል።"),
    (18, 4, "በመስዕ ፡ በኩል ፡ አንደ ፡ ፈሰሰ ፡ ወደ ፡ ምዕራ ብም ፡ ይፈሳል ፡ ከዚያም ፡ ወደ ፡ አራቱ ፡ ማዕ iN ይሄዳል ፡ ከዚያም ፡ ውሀና ፡ ጠል ፡ ይገ።"),
    (18, 5, "(ትእምርት ፡ ነው ፡) es በራ ፡ ወደ ፡ ሌላ ፡ ቦታ ፡ ሄዩ ፡ ወደዚህ ተራራ ፡ ምሥራቅ ፡ ቀረብሁ።"),
    (
        18,
        6,
        "በዚያም ፡ ሕግ ፡ የሚጠበቅበቸው ፡ አንኳጨቶ ችን ፡ አየሁ ፡ ይልቁንም ፡ የከርቤና ፡ የነጭ ዕጣን ፡ መዓዛ ፡ ያለበቸው ፡ የቅመም ፡ አንጨኔቶ ችን ፡ አየሁ ፡ እንጨቶችም ፡ አይመሳሰሉም።",
    ),
    (18, 7, "አነሱንም ፣ ክየሁ ፡ በኋላ ፡ ወደ ፡ ምሥራቅ ፡ ተራራ ፡ ሄድሁ ፡ ፈጽሜም ፡ የራቅሁ ፡ አይደለ ሁም።"),
    (18, 8, "የማይገታ ፡ ውሀ ፡ ያለበቸው ፡ ሌላ ፡ የቈላዎች፡ ቦታን ፡ አየሁ።"),
    (18, 9, "ያማረ ፡ እንጨትንም ፡ አየሁ ለውዝ ፡ ሽታ ፡ ነው።"),
    (18, 10, "በነዚህ ፡ ቈቂላዎች ፡ አጠገብም ፡ መዓዛ ፣ ያለው ፡ ሽታ ፡ አየሁ።"),
    (18, 11, "አኒህን ፡ ካየሁ ፡ በኋላ ፡ ወደ ፡ ምሥራቅ ፡ ቀረ ብሆ ፡ በውስጡ ፡ አንጨቶች ፡ የሉበት ፡ ሌላ ፡ ተራራንም ፡ አየሁ።"),
    (18, 12, "ሣሪራ ፡ ከልበኔም ፡ አንደሚባበል ፡አንደ፡ ነቁጥሮ፡ ያለ ፡ ውሀ ፡ ይፈሳል።"),
    (18, 13, "በዚያው ፡ ተራራ ፡ ላይ ፡ ሆኝ ፡ ሌላ ፡ ተራራ አየሁ ፡ በውስጡም ፡ ዋግራ ፡ የሚበሉ ፡ አንጨ ቶች ፡ አሉበት።"),
    (18, 14, "አኛም ፡ አንጨቶች ፡ ከርክዕ ፡ የሚባል ፡ ሽቱ የተመሉ ፡ ጽናትንም ፣ ያገኙ ፡ ናቸው ፡ ይህን ንም ፡ ሽቱ ፡ በቈረጡት ፡ ጊዜ ፡ ክሽቱ ፡ ሁሉ ይበልጣል።"),
    (18, 15, "አነዚህን ፡ ሽቶት ፡ ካየሁ ፡ በኋላ ፡ ወደ፡ መስዕ ፡ እየተመለከትሁ ፡ ወደ ፡ ተራሮች ፡ ሄድሁ።"),
    (18, 16, "ያማረ ፡ ሽቱን ፡ መዓዛ ፡ ያላቸው ፡ አንጨቶች ንም ፡ ቀናንሞስ ፡ የሚባል ፡ ሽቱን ፡ ፕፕሬ፡ የሚበል ፡ ሽቱን ፡ የተመሉ ፡ ሰበቱን ፡ ተራራ ዎች ፡ ሄድሁ።"),
    (19, 1, "ከዚያም ፡ በነዚያ ፡ ተራሮች ፡ ላይ ፡ ርቁ ፡ ወደ፡ ምሥራቅ ፣ ጌድሁ።"),
    (19, 2, "ወደ ፡ ኤርትራ ፡ ባሕርም ቦታ ፣ የራቅሁ ፡ ሆንሁ።"),
    (
        19,
        3,
        "ዙኵጡኤል ፡ በሚባል ፡ መልአክ ፡( ዓቃቤ ፡ ገነት ፡ ሃው ፡} በላይ ፡ አልፌ ፡ ሄድሁ ፡ በቸርነቱም ፡ ወደምት ወረስ ፡ ገነት ፡ መጣሁ ፣ ከኒህ ፡ አንጨቶች ፡ ወዲያ ብዙዎች ፣ ታላላ ቆች ፡ አንጨቶችን ፡ በዚያ ፡ በቅለው ፡ አየሁ።",
    ),
    (20, 1, "ሽታቸውም ፡ ያማረ፡ ሲሆን ፡ ታላላቆች ፡ናቸው፡ ብርሃናቸውም ፡ ብዙ ፡ ነው ፡ እነሱም ፡ ያበራሉ።"),
    (
        20,
        2,
        "ከሱ ፡ በልተው ፡ ታላቅ ፡ ጥበብን ፡ የሚያውቁ በት ፡ የጥበብ ፡ አንጩጨትን ፡ አየሁ ፡ ተረርቃ ፡ ስታውም ፡ እንደ፣ ፡ ቱድሁ ፡ ከዚያም i] ክርስቲያን ሃይማዛ፥ ትና ሥርዓት።",
    ),
    (20, 3, "ደ፡፱፡ BPH ከዚያም ፡ በታ ፡ በምድር ፡ ዳርቻ ፡ ወደ ፡ ዓዚብ ፡ ሄድሁ።"),
    (20, 4, "በዚያም ፡ ቦታ ፡ የተከፈቱ ፡ ሦስት ፡ የሰማይ መስከቶችን ፡ አየሁ ፡ ከዚያም ፡ ቦታ ፡ ዋዕይ ፡ ዛ ፥ ዝናም ፡ ነፋስም ፡ ሬነፍላሳል።"),
    (20, 5, "ከዚያም ፡ ቦታ ፡ ተነሥቼ ፡ በሰማይ ፡ ዳርቻ ፡ወደ፡ ፀሐይ ፡ መውሪኳ ፡ ሄድሁ።"),
    (20, 6, "በዚያም ፡ ቦታ ፡ ሳለሁ ፡ በፀሐይ ፡ መውጫ ፡ በዙል ፡ የተከፈቱ ፡ሦስት ፡ የሰማይ ፡ ደጃፎችን፡ የሁ።"),
    (20, 7, "ተናናሽ ፡ ደጃፎችም፡ላይ፡ ከነዚሀ ደጃፎች፥ ያንዳንዱ ፡ ተናናሾ ች ፡ የሰማይ ፡ ኮከቦች፡ ይገ በታል።"),
    (20, 8, "ታየ ችላቸውም ፡ ጎዳና ፡ ወደ ፡ ፀሐይ ፡ መግ ያ ፡ ይሄዳሉ።"),
    (
        21,
        1,
        "ህነንም ፣ በየሁ ፡ ጊዚ ፡ ፈጣሪን ፡ አመሰገንሁ ፡ ፍጥረቱን ፡ ገናንነት ፡ ለሰዎች ፡ ሰውነቶችና መላእክት ፡ ሲገልጥ ፡ የሚያበሩና ፡ ታላላቅ ፡ ተአምራቶችን ፡ ያደረገ፡ የክብር ፡ ባለቤት፣፡ጌታ ም ፡ በየጊዚው ፡ አመሰግነዋለሁ።",
    ),
    (
        21,
        2,
        "ጥረቱን ፣ ያመሰግኑ ፡ ዘንድ ፡ ፍጥረቱም ፡ ሁሉ ፡ የኃይሉን ፡ ሥራ ፡ ያዩ ፡ ዘንድ ፡ ታላቅ ሆን ፡ የቃሉንም ፡ ሥራ ፡ ያመሰግኑ ፡ ዘንድ ሱንም ፡ ለዘላለሙ ፡ ያመሰግኑት ፡ዘንድ፡ ይኽ ን ፣ አደረገ።",
    ),
    (
        21,
        3,
        "የያሬድ ፡ ልጅ ፡ ሄኖክ ፡ በሌላ ፡ ጊዚ፡ ያየው፡ በብ ፡ ያለበት ፣ ራዕይ ፡ ይህ ፡ ነው ፡ ያሬድን መላልኤል ፡ ልጅ ፡ አለው ፡ መላልኤልን፡የቃ ናን፡ ልጅ ፡ አለው ፡ ቃይናንን ፡የሄኖስ፡ልጅ፡ ለው ፡ ሄኖስን ፡ የሴት ፡ ልጅ ፡ አለው ፡ ሴትን፡ የአዳም ፡ ልጅ ፡ አለው = ዚሀም ፡ ዓለም ፡ ላሉ ፡ ሰዎች ፡ አናገረው ንድ ፡ የጀመርሁት ፡ የዘጠኙ ፡ ሕገጋት ፡ አበ ጋዝ ፡ ይህ ፣፡ ኢታምልክ ፡ ነው።",
    ),
    (
        21,
        4,
        "ቀድሞ ፡ ሰዎች ፡ ይኽንን ፡ ነገር ፡ ሰሙ ፡ በኋ ም ፡ የተነሣችሁ ፡ሰዎች ፡ በመላእክት ፡ ጌታ ፡ ት ፡ የምናገረው ፡ የከበረ ፡ የኢታምልክን ፡ ር ፡ አስተውሉ = ለዚህ ፡ የአበው ፡ ነገራቸው ፡ ከዘጠኙ ፡ ሕገ ች ፡ አ.ታምልክ ፡ ይበልጣል ፡ ማለት ፡ ነው ፣ ኛም ፣ በኋላ ፣ የተነሣን ፡ ሰዎች ፡ ከዘጠኙ • ገጋት ፡ አ.ታምልክ ፡ ትበልጣለች ፡ ማለትን ፡ ንከለክልም = ፡ አንዳሰብሁት ፡ ዘላለም ፡ ጸንቶ ፡ የሚኖር ሕይወት ፡ አድል ፡ ከሱ ፡ የተሰጠኝ ፡ የመላእ ት ፡ ጌታ ፡ እንደ ፡ ወደደ ፡ ዛሬ ፡ የያዝሁት ፡ በብ ፡ ከመላእክት ፡ ፊት ፡ እስከ ዛሬ፡ ድረስ።",
    ),
    (21, 5, "ልተሰጠኝም ፡ ነበር።"),
