    (52, 9, "አሁንም ፡ መላአክት ፡ እንጨቶችን ፡ ያምጡ ልህ ፡ መላእክት ፡ ለዚያ ፡ ሥራ፡ በወጡ ፡ ጊዜ፡ አጄን ፡ ጭኘ ፡ መርከብን ፡ አጠብቃታለሁ።"),
    (53, 1, "ከመርከብ ፡ ወጥተህ ፡ ሕይወት ፡ ያለው ፡ ዘር ፡ ትሆናለህ ፡ ይህ ፡ ዓለም ፡ በዶውን ፡ አንዳ ይቀር፡ በሞተው ፡ ለውጥ ፡ ይግባ።"),
    (53, 2, "ልጅህንም ፡ ለዘላለም ፡ በፊቱ ፡ አጸናዋለሁ ፡ ከንተ ፣ ጋራ ፡ የሚኖሩ ፡ ልጆችህንም ፥ በዚህ፡ ዓለም ፡ አበዛቸዋለሁ።"),
    (53, 3, "በመላአክት ፡ ጌታ ፡ ስም ፡ ያመነ ፡ ሰውም።"),
    (53, 4, "በዚህ ፡ ዓለም ፡ ይበዛል ፡ ይከብራል።"),
    (
        53,
        5,
        "it ግፍን ፡ ያስተማሩት ፡ እነዚያን ፡ ደቂቁ ፡ ሌት ንም ፡ መላእክት ፡ የብርና ፡ የወርቅ ፡ የይርና፡ የብረት ፡ የናስም ፡ ተራሮች ፡ በሉበት ፡ በምፅ ራብ ፡ አያቴ ፡ ኔኖክ ፡ ቀድሞ ፡ በሳየኝ ፡ በምት ተ ክርስቲያን ሃይማኝ ትና ሥርዓት ፲፲፡፤፱፡።",
    ),
    (53, 6, "በዚያችም ፡ ቀን ፡ ቅዱስ ፡ ካኤል ፡ የመን ስ ፡ ቅሩስ ፡ ዕውቀቱ ፡ ወደ ፡ ኃዘን ፡ ሬወስደ ል ፡ ያበሳሠኛል ፡ ብሎ ፡ ለቅዱስ ፡ ሩፋኤል ፡ ለሰለት።"),
    (
        53,
        7,
        "ቂቀ ፡ ሴት ፡ ስለ“ቀበሏት ፡ ስለ ፡ ተሠወረች ም ፣ መከራ ፡ ስለ ፡ መጨነቅስ = ትሠራ ፡ የኖረች ፡ አነሱም ፡ በፊቷ ፡ አንደ፡ ም ፡ የሚቀልጡባት ፡ የመከፉይቱን ፣ ጭንቅ ታገሥ ! የቻለው ፡ ማነው ፡ ብሎ ፡፣ መለሰ ት።",
    ),
    (
        54,
        1,
        "ግመኛ ፡ ቅዱስ ፡ ሚካኤል ፡ ሩፋኤልን ፡ በዚች ፡ ገር ፣ ልቡናውን ፡ የሚያራራ ፡ ከዚችም ፡ ቃል፡ ተነሣ ፡ ኵላለሊ.ቱ ፡ የማይተዋወክበት ፡፣ ማነው ፡ ሎ ፡ መለሰለት።",
    ),
    (54, 2, "ከራም ፡ መጣባቸው ፡ መከራዎችንም ፡ አንደ ህ ፡ ያመቸው ፡ በኃ„ኪጸታቸው ፡ ነው።"),
    (
        54,
        3,
        "መማለድም ፡ በመላእክት ፡ ጌታ ፡ ፊት ፡ በቆመ፡ ዚ ፡ እንዲህ ፡ ሆ፣፡ ቅዱስ ፡ ሚካኤል ፡ ሩፋኤ ን ፡ እንዳ.ህ፡ አለው ፡ የመላአክት ፡ ጌታ ፡ ተቂ ቷቸቁልና ፡ በጌታ ፡ ፊት ፡ ይቅርታ ፡ አይደረ ግላቸው ፡ አለው።",
    ),
    (54, 4, "ጌታ ፡ አምሳል ፡ ጣፆቱን ፣ ይሠራ ሉና ፡ ስለ y ፡ ነገር ፡ ለዘላለሙ ፡ የተሠወረ ፣ መከራ ፡ መጣበቸዋል።"),
    (
        54,
        5,
        "ነሱ ፡ ብቻ ፡ መቻያቸውን ፡ ለዘላለሙ ፡ ተቁበ ት ፡ አንጂ ፡ አለቃም ፡ ቢሆን ፡ ጭፍራም ፡ ሆን ፡ ያንዱን ፡ መከራ ፡ አን ፡ አይቀበለው ና ፡ ስለዚህ ፡ መከፉ ፡ ትመጣባቸዋለች።",
    ),
    (54, 6, "ዚሀ ፡ ዓለም ፡ ለሚኖሩ ፡ ሰዎች ፡ ይችን፡ ኃጢ. ት ፡ ገልጠው ፡ ለስተምረዋልና ፡ ከዚህ ፡ መክ ቸው ፡ በኋላ ፡ አጋንንት ፡ ያስደነግኳቸዋል ፡ ላዝሂቸቱል።"),
    (54, 7, "ነዚያም ፡ የአጋንንት ፡ ስማቸው ፡ አነሆ ፡ አን . ፡ ነው ፡ የዪቁቀ ፡ ትም ፡ ስማሣቸው ፡ ሬህ ፡ ው።"),
    (54, 8, "ለቃቸው ፡ ስማዝያ ፡ ነው ፡ ሁለተኛው ፡ ኣር ከኪ.ፋ፡ ነው ፡’ስተኛውም ፡ አርን ፡ነው ፡ ራተናኛውም ፡ ኮከብኤል ፡ነው።"),
    (
        54,
        9,
        "ምስተኛውም ፡ ጡርኤል ፡ ነው ፡ ስድስተኛ ም ፡ ሩምያል፡ነው ፡ ሰበተኛውያም ፡ ዳንኤል ፡ ምንተኛውም ፡ ምቃኤሌል ፡ ነው ፡ ዘጠኝኛ ም ፡ በራ. ቃኤል ፡ ነው ፡ አሥረኛው ፡ አዛዝ ል፡ነው ፡ አሥራ ፡ አንደኛውም ፣ አርማሮስ፣ - ፡ አሥሪ.፡ ሁለተኛውም ፡ በስርያል ፡ነው።",
    ),
    (
        54,
        10,
        "ረ. ፡ ሥስተኛው ፡ በስላኤል ፡ ነው ፣ አሥሪረ.፡ ራተኛውም ፡ አናንያል ፡ ነው ፡ አሥራ ፡ አም ተኛው ፣ ጡርያል ፡ ነው ፡ አሥራ ፡ ስድስተ ውም ፡ ሰሲምሰታፓኤል ፡ ነው።",
    ),
    (
        55,
        1,
        "ራ. ፡ ሰባተኛውም ፡ ይታርኤል ፡ ነው ሥራ ፡ ስምንተኛው ፡ ቱማኤል፡ነው ፡ አሥራ ጠኝኛውም ፡ ጥራኤል ፡ ነው ፡ ሀያየኛውም ፡ [ny |=: 185 ክርስቲያን ሃይማዛትና ሥርዓት nክ።",
    ),
    (55, 2, "አግዚአብሔር ፡ በዚህ ፣ ዓለም ፡ በጌትነት ፡ በናረ ፡፣ ጊዚ ፡ ለቅዱሳን ፡ የገለጠው ፡ የመሐላ ፡ ፍጸሜ ፡ የክስብኤል ፡ የስሙ ፡ ቁጥር ፣ ይህ ነው።"),
    (
        55,
        3,
        "ሁለተኛውም ፡ ስሙ ፡ ቤቃ ፡ ይበላል ፡ይኽኸውም፡ አጋንንት ፡ያንን ፡የተሠወረ፡ ስሙን ፡ ይሰሙት፡ ዘንድ ፡ቅዱስ፡ ሚክኤልን፣ የተሠወረ ስሙን ግለጥላቸው ፡ አለው ፣ የተሠወረው EN አት፡ለሰው፡ልጀች፡ ያስተማሩ ፡ አጋንንት ፡ ከዚያ ፡ መሐላና ፡ ክዚያ ስም ፡ የተነሣ ፡ ይንቀጠቀጡ ፡ ዘንድ ፡ በመሐ ላም ፡ ጊዚ ፡ ይጠሩት ፡ ዘንድ ፡ ያንን ፡ የተሠ ወረ ፡ ስሙን ፣፡ ግለጥላቸው ፡ አለው።",
    ),
    (
        55,
        4,
        'ኃይለኛ ፡ ነውና ፡ የጸናም ፡ ነው "0 ፡ የዚህ ፡ የመ ሐላ ፡ ምሥጢሩ ፡ ይህ ፡ ነው ይኸንንም ፡ ስም ፡ ከሃሊ ፡ የሚሆን ፡ አምላክ ፡ በቅዱስ ፡ ሚካኤል ፡ እጅ ፡ አኖረው ፡ የዚህም ስም ፡ የተሠወሩ ፡ ምሥመ.ሮቹ ፡ አነህ ፡ ናቸው ፍጥረታቱም ፡ ሁሉ ፡ በመሐላው ፡ ጸና።',
    ),
    (
        56,
        1,
        "በዚህም ፡ ስም ፡፣ ሰማይ ፡ፀና ፡ዓለም ፡ ሳይፈጠር ነበር ፡ አስከ ፡ዘላለሙም ፡ ይኖራል ፡ ምድርም በሱ ፡ በውሀው ፡ ላይ ፡ PN ከተራሮ ችም ፡ ውስጥ ፡ ከጥንት ፡ ጀምሮ፡ እስክ ፡ ዘላለሙ ፣ ድረስ ፣ የጣፈጡ ፡ ውሀዎች ፡ ይመነ ሪዃሉ።",
    ),
    (
        56,
        2,
        "በዚያም ፡ ስም ፡ በሕር ፣ ተፈጠረች ፡ መሠረ ቷም ፡ ተፈጠረ ፡ በተቈቂጣችም ፡ ጊዚ ፡ አንዳት ወጣ ፡ በሽዋ ፣ ገደበት ፡ ከጥንት ፡ ጀምሮ ፡ እስክ ዘላለሙ ፡ ድረስ ፡ ከድምበኗ ፡ አታልፍም።",
    ),
    (56, 3, "በዚያም ፡ ስም ፡ ጥልቅ ፡ ውሀዎች ፡ ሁሉ ፡ ጸን ተው ፡ ኖሩ ፡ ከጥንት ፡ ጀምሮ ፡ አስከ ፡ ዘላለሙ ድረስ ፡ ከቦታቸው ፡ አይወጡም።"),
    (
        56,
        4,
        "በዚያም ፡ ስም ፡ ጨረቃና ፡ ፀሐይ ፣ ጎዳናቹ ውን ፡ ይጨርሳሉ ፡ ከጥንት ፡ ጀምሮም ፡ አስክ ፡ 1010 [iy 5 Hy) iy) ዘሳለሙ ፣ ድረስ ፡ ክዘዛቸው ፡ ትእዛዝ ፡ አልወ ጠም።",
    ),
    (56, 5, "በዚያም ፡ ስም ፣ ኮከቦች ፡ ጎዳናቸውን ፡ ይጨር ሳሉ ፡ ስማቸውንም ፡ ይጠራል ፣ እነሱም ፡ ክጥ ንት ፡ ደምሮ ፡ አስከ ፡ ዘላለሙ ፡ ድረስ ፡ ይሰሙ ታል።"),
    (56, 6, "አንደዚሁ ፡ ነፍሳት ፡ ሕይወት ፡ የሚሆኗቸው፡ የውሀዎች ፡ አካሎች ፡ የነፋዕችም ፡ ሁሉ ፡ አክ ሎች ፡ ከነፋሶች ፡ ቅመምነት ፡ ሁሉ ፡ የተገኙ።"),
    (56, 7, "ሥራዎቻቸውም ፡ ተፈጠሩ።"),
    (56, 8, "በዚያም ፡ ቦታ ፡የነጐድጓድ፡የቃሉ፡ በታዎች፡ ይጠበቃሉ ፡የመብረቅም፡ ብርሃን ፣፡ይጠበቃል።"),
    (57, 1, "በዚያም ፡ ቦታ ፡የውርጭና ፡የበረድ፡ በታዎች፡ የጉምም ፡ በታዎች ፡ የጤዛና ፡ የዝናም ፡ በታ ዎች ፡ ይጠበቃሉ።"),
    (57, 2, "በነዚያም ፣ ሁሉ ፡ በመላአክት ፡ ጌታ ፡ ፊት ፡ ome) en) vee if፣ ክርስቲያን ሃይማዛ፣ ትኛ ሥርዓት ክ።"),
    (57, 3, "፡ አሳት ፡ ብርሃን ፡ እንደ ፡ ፅንቀ ፡ ያበራል ፡ በሀ ታት ፡ ጌታ ፡ ፊት ፡ በፊቴ ፡ ፍግ ፡ ብዬ ፡ ወደ ሁ።"),
    (
        58,
        1,
        ") መላአክት ፡ አለቁች ፡ አንዱ ፡ መልአክ ፡ “ስካ ል ፡ ቀኝ ፡ እዚን ፡ ይዘ ፡ አነሣኝ ይቅርታው ፡ ደ ፡ ተሠወረበት ፡ ቦታ ፡ ሁሉ ፡ ቸርነቱም ደ ፡ ተሠወረበት ፡ በታ ፡ አወጣኝ።",
    ),
    (58, 2, "ሰማይ ፡ ዳርቻ ፡ የተሠወሩትንም፡ ሁሉ ፡ የክ ክብትንም ፡ ቦታዎች ፡ ሁሉ ፡ ለሰው ፡ ሊያበሩ ፡ ሚወጡ፡የብርሃኖችንም፡ሁሉ፡ቦታ፡ አሳየኝ።"),
    (58, 3, "ንፈስ ፡ ቅዱስም ፡ ሄኖክን ፡ በሰማዮች ፡ በላይ፡ ለ ፡ ሰማይ ፡ ሠወረው።"),
    (58, 4, '(ጸራቀቀው ፡} ዚያም ፡ ብርሃን ፡ መክከል ፡ በዕንቀ" ፡ የተሠራ ፡ ትን ፡ አየሁ።'),
    (58, 5, "ነዚያም ፡ ድንጋዮች ፡ መክከል ፡ ደጎነኛ ፡የሚ ን ፡ የአሳት ፡ (መንፈስ ፡ ቅዱስ ) አንደበቶች መምህራን ) አሉ ፡ አለ።"),
    (
        58,
        6,
        "ውነቴም ፡ አሳት ፡ የሚከበው ፡ የዚያን ፡ቤት፡ ሪያ ፡ አየች ፡ በዚያም ፡ ወንዝ ፡፣ በራቱ ፡ ማዕ ን ፡ ሕያው ፡ የሚሆን ፡ የጌታን ፡ ጸጋ ፡ ክብር ፡ ተመሉ ፡መምራን ፡ አሉበት።",
    ),
    (59, 1, "ሩቤልና ፣ ሱራፌል ፣ አፍኒን ፡ የዚህን ት ፡ ዙሪያውን ፡ ከበውታል ፡ እነዚህም ፡ የማ ርፉ ፡ ናቸው ፡ የጌትነቱንም ፡ ዙፋን ፡ ይጠብ ሉ።"),
    (59, 2, "ማይቁጠሩ ፡ የብዙ ፡ ብዙ ፡ የሚሆኑ ፡ መላእ ትን ፡ አየሁ።"),
    (59, 3, "ብርኤልና ፡ ሚካኤል ፡ ፋኑኤል ፡ ሩፋኤል ፡ ንን ፡ ቤት ፡ ይከቡታል ፡ በሰማይ ፡ ያሉ ፡ የከ ሩ ፡ መላእክትም ፡ በዚያ ፡ ቤት ፡ ይወጡ ፡ ገቡ ፡ ነበር።"),
    (60, 1, "ዚያም ፡ቤት ፡ ገብርኤልና ፡ ሚከኤል ፡ ፋኑኤ ና ፡ ሩፋኤልም ፡ ብዙ ፡ የሆኑ ፡ ቁ.ጥር ፡ የሌላ ው ፡ ሌሉች ፡ መላእክት ፡ የከበሩ ፡ ወጡ።"),
    (60, 2, "ሉየ ፡ መዋዕልነት ፡ ገንዘበ ፡ የሚሆን፡ጌታም፡ ነሱ ፡ ጋራ ፡ አለ ፡ ራሱም ፡ እንደ ፡ ብዝት ፡ ጭ ፡ ነው ፡ንጸ.ሕ ፡ ነው ፡ ልብሱም ፡ የማይ ረጐም ፡ነው።"),
    (60, 3, "ኔም ፡ በግምበሬ ፡ ፍግም ፡ ብዬ ፡ ወደቅሁ ፡ ጋዬም ፡ ሁሉ ፡ አንደ ፡ ሰም ፡ ቀለጠ ፡ አአም ሮዬም ፡ ተለወጠ።"),
    (60, 4, "ፓላቅ ፡ ቃል ፡ እውቀት ፡ በለበት ፡ ልቡና ፡ ሰምቼ ፡ ጮኩ ፡ ፈጽሜም ፡ አሱን ፡ አመሰገ ሁ ፡ ስሙንም ፡ አከበርኩ።"),
    (60, 5, 'ፌ ፡ የወጡ ፡ እኒህ ፡ ምስጋናዎች ፡ ዕለተ ፡ ሑድ ፡ ገንዘቡ ፡ በሆነችለት ፡ በዚያ ፡ በጌታ ፡ ት "የተወደዱ ፡ ሆኑ ፡ አለ።'),
    (
        60,
        6,
        "ሉየ ፡ መቁዋዕልነት ፡ ገንዘቡ ፡ የሚሆን ያም ፡ ታ ፡ ከገብርኤልና ፣ ከሚካኤል ፡ ከፋኑኮኤልና ፡ ሩፋኤልም ፡ ቀጥር ፡ ከሌላቸው ፡ የብዙ ፡ብዘዙ፡ ሚሆኑ ፡ መላእክትም ፡ ጋራ ፡ ወደኔ ፡ መጣ።",
    ),
    (60, 7, "ም ፡ መልልክ ፡ ወደኔ ፡ መጣ ፡ በቃሉም ፣ ተና ረኝ ፡ አለ።"),
    (60, 8, "ጎ ፡ ሥራ. ፡ የተወለደ ፡ የባለ ፡ አአምርሮ፡ልዬ ፡ aéi ai፣ iy iE: i=; ክ።"),
    (60, 9, "ተ ክርስቲያን ሃይደማዛትና ሥርዓት [I ዙሪያ ፡ነው ፡ ሁለመናው ፡ የሚያቃጥልና ፡የሚ ያበራ ፡አሳትን ፡ የተመላ ፣ ነው።"),
    (60, 10, "ወደሚሄድበቸውያም ፡ ሠረገላዎች ፡በወጣ፡ጊዜ፡ ሠረገላዎችን ፡ የሚነዳ ፡ ነፋስ ፡ ይነፍሳል።"),
    (
        60,
        11,
        "ፀሐይም ፡ ከምሥራቅ ፡ ወደ ፡ ምፅራብ ፡ ይገባል ወደ ፡ ምሥራቅም ፡ ለመሄድ ፡ ከምዕራብ ፡ ወይ መስዕ ፡ ይመለሳል ፡ ወደዚህም ፡ መስከት ፡ ሊገበ፡ ይመራል ፡ በሰማይም ፡ ሁኖ ፡ ያበራል።",
    ),
    (
        60,
        12,
        "አሁን ፣ አንደ ፡ ተናገርሁት ፡ በመጀመሪያው ወር ፡ በታላቁ ፡ መስኮት ፡ ይወጣል ፡ በአራተኛ ይቱም ፡ ደጃፍ ፡ ይወጣል ፡ ይችውም ፡ አራተኛ ይቱ ፡ ዪዶጃፍ ፡ ፀሐይ ፡ በምሥራቅ ፡ ከሚወጣባበ ቸው ፡ ስለዚህ ፡ ከስድስቱ ፡ ደጃፎች ፡ አንዲቱ ናት።",
    ),
    (
        60,
        13,
        "በመጀመሪያው ፡ ወር ፡ ፀሐይ ፡ ከሷ. ፡ ከሚወጣ በት ፡ በዚያችም ፡ በአራተኛይቱ ፡ ደጃፍ ፡ በዛ መናቸው ፡ በሚከፈቱበት ፡ ጊዜ ፡ ክነሱ ፡ ዋዕይ ፣ የሚወጣባቸው ፡ አሥራ ፣ ሁለት ፡ ደጃፎች ፡።",
    ),
    (60, 14, "ፀሐይ ፡ ከምሥራቅ ፡ በወጣ ፡ ጊዜ, ፡ በዚች ፡ በአ ራተኛይቱ ፣ ደጃፍ ፡ ሠላሳ ፡ ቀን ፡ ይወጣል።"),
    (60, 15, "በሰማይ ፡ ክለው ፡ መግቢያ ፡ በአራተኛይቱ፡ ደጃፍ ፡ አቅንቶ ፡ ይወርዳል።"),
    (60, 16, "በነዚያም ፡ ወራት ፡ አስከ ፡ ሠላሳ ፡ ቀን ፡ ድረስ፣ ቀኒቱ ፡ ከቀን ፡ ትረዝማለች ፡ ሌሊቱም ፡ ከሌ ሊት ፣ ታጥራለች።"),
    (60, 17, "በዚችም ፡ ቀን ፡ ቀኒቱ ፡ ከሌሊቱ ፡ሁለት ፡ አጅ ትበልጣለት።"),
    (60, 18, "ጠንቅቀው ፡ ቢቈጥራት ፡ ቀኒቱ ፡ አሥር፡ክፍል፡ ትሆናለች ፡ ሌሊቱም ፡ ስምንት ፡ ክፍል ፡ ትሆ ናለች።"),
    (60, 19, "ፀሐይም ፡ ከዚች ፡ ከአራተኛ ይቱ ፡ ደጃፍ ፡ ይወ ጣል ፡ በአራተኛ ይቱቻም ፡ ደጃፍ ፡ ይገባል።"),
    (60, 20, "ሠላሳ ፡ ቀን ፡ በምሥራቅ ፡ ወዳለችው ፡ ወዳም ስተኛይቱ ፣ ይመለሳል ፡ ከሷም ፡ ወጥቶ ፡ በምስ ተኛይቱ ፡ ደጃፍ ፡ ይገበል።"),
    (
        60,
        21,
        "ያን ፡ ጊዜም ፡ ቀኒቱ ፡ ሁለት ፣ እጅ ፡ ትበልጣ ለች ፣፡ቀሂቱም ፡ አሥራ ፡ አንድ ፡ ክፍልን ፡ ትሆ ናለች ፡ ሌቲቱም ፡ ታጥራለች ፡ ሰበት ፡ ክፍል ንም ፣ ትሆናለች።",
    ),
    (
        60,
        22,
        "ፀሐይም ፡ ወደ ፡ ምሥራቅ ፡ ይመለሳል ፣ ወዬ ፡ ስድስተኛይቱም ፡ ደጃፍ ፡ ይገበል ፡ የጳጉሜ ቁን ፡ ከሷ. ፡ ጋራ፣፡ስለ፡ናረች፡ በስድስተኛይቱ ፡ ደጃፍ ፡ ሠላለ፡ አንድ ፡ቀን፡ ይወጣል ፡ ይገባል።",
    ),
    (60, 23, "በዚያትም ፡ ቁን ፡ ቀሂቱ ፡ ከሴለሊ.ቱ ፡ ትረዝማ ለች ፡ቀኒቱም ፡ የሌሊቱ ፡ አጥፍ ፡ ትሆናለች ቀሂቱም ፡ አሥራ ፡ሁለት ፡ክፍልን፡ትሆናለች።"),
    (60, 24, "ሴቲቱም ፡ አጥራ ፡ ስድስት ፡ ክፍልን ፡ ትሆና ለች።"),
    (60, 25, "(ሰኔ፡) ቀቱ ፡ ታጥር ፡ ዘንድ ፡ ሴቲቱም ፡ ትረዝም ፡ ዘንድ ፡ ዐሐይ ፡ ወደ ፡ ሰማይ ፡ ዳርቻም ፡ ይመ ለሳል።"),
    (61, 1, "ዐየሐይም ፡ ወደ ፡ ምሥራቅ ፡ ተመልስ ፡ ወደ ፡ ስድስተኛው ፡ መስኮት ፡ ይገባል ፡ ከቧ ፡ ይወ 1015 ተ ክርስቲያን ሃይማዛ ትና ሥርዓት = ጽቋ፡ጽ።"),
    (61, 2, "ሐይም ፡ መስከቶችን ፡ ጨረሰ ፡ ዳግመኛም ፡ ህ ፡ መስከቶች ፡ ላይ ፡ ዙሮ ፡ ሠላሳ ፡ ቀን፡ ዚያ ፡ መስከት ፡ ይገበል ፡ በመግቢያውም ፡ ትክክል ፡ ይገባል።"),
    (
        61,
        3,
        "ዚያችም ፡ ቀን፡ሌሊፒቲቱ ፡ ከርዝመቷ፡ አንድ ጅ ፡ ታጥራለች ፡ ይኸውም ፡ አንድ ፡ ክፍል ው ፡ ሌለ.ቲቱ ፣ አሥራ ፡ አንድ ፡ ክፍል ፡ ቀኒ ም ፡ ሰባት ፡ ክፍል ፡ ትሆናለች።",
    ),
    (61, 4, "ሐይም ፡ ተመልፅ ፡ በምሥራቅ ፡ ወደሚወጣ ት ፡ ወደ ፡ ሁለተኛው ፡ መስኮት ፡ ገበ ፡ በዚ ም ፡ መስከት ፡ ተመልሰ ፡ ሠላሳ ፣ ቀን ፡ ይወ ል ፡ ይገበል።"),
    (61, 5, "ዚያችም ፡ ቀን ፡ ሌሊቲቱ ፡ ከርዝመቷ ፡ ታጥ ለች ፡ ሌሊቲቱ ፡ አሥር ፡ ክፍል ፡ ቀኒቱም ፡ ምንት ፡ ከፍል ፡ ትሆናለች።"),
    (61, 6, "ዚያችም ፡ ቀን ፡ ፀሐይ ፡ ከዚያች ፡ ከሁለተኛ ቱ ፡ መስከት ፣ ይወጣል ፡ በመግቢያውም ብቶ ፡ ወደ ፡ ምሥሪ.ቀ ፡ ይመለላል።"),
    (61, 7, "ሐይም ፡ የጳጉሜ ፣ ቀን ፡ ገብታ ፡ ስለ ፡ ተቂጠ ች ፡ በሦስተኛ ይቱ ፡ መስከት ፡ ሠላሳ ፡ አንድ ፡ ን፡ወጥቶ፡በሰማይ፡በለ፡መግቢያው፡ይገበል።"),
    (61, 8, "ዚያችም ፡ ቀን ፡ሌሊቲቱም ፡ ታንሳለች ፡ ሌሊ ቱም ፡ ዘጠኝ ፡ ቀሂቱም ፡ ዘጠኝ ፡ ክፍል ፡ ትሆ ለች።"),
    (61, 9, "ሊ.ቱም ፡ ከቀኑ ፡ ጋሪ. ፡ ይተክከላል ፡ ዓመቱም ንቅቆ ፡ቢቁጥሩት ፡ ሦስት ፡ መቶ ፡ ስላ፡ አራት ‘ይሆናል።"),
    (61, 10, "ሌሊትና ፡ የቀን ፡ ርዝመቷ ፡ የሴለ.ትና ፡ የቀ ም ፡ ማጠ ፡ በፀሐይ ፡ መንገድ ፡ ዕለያል።"),
    (61, 11, "ለዚህም ፡ ጎዳናው ፡ ይረዝማል ፡ አንዱ ፡ቀን፡ ንዱ ፡ ቀን ፡ አንዱም ፡ ሴሊት ፡ ክንዱ ፡ ሌለ.ት፡ ጥራል።"),
    (61, 12, "ፀሐይ ፡ ሥራት ፡ መንገዱም ፡ መመለሱም ፡ ፡ነው።"),
    (61, 13, "ተመለሰዎም ፡ ጊዜ ፡ ስሳውን ፡ ከንትሮስ ፡ ለ.ፈ ም ፡ ይመለሳል ፡ ተመልዕም ፡ በምሥራቅ ወጣል ፡ ለዘለዓለም ፣ የሚኖር ፡ ታላቅ ፡ ብር ም ፡ ይህ ፡ነው።"),
    (62, 1, "፡ እንዳዘዘ ፡ በሱ፡ አምሳል ፡ የሚጠራ ፡ ከም ራቅ ፡ የሚወጣ ፡ ደገኛ ፡ ብርሃን ፡ ሬህ፡ነው።"),
    (62, 2, "ዳ.ህ ፡ ሆና ፡ ይወጣል ፡ ይገበል ፡ መፐጕደልም፡ ለበት ፡ በሠረገላ ፡ ሆኖ ፡ በመዓልትም ፡ በሌለ. ም ፡ ይሮጣል ፡ አንጂ ፡ አያርፍም።"),
    (62, 3, "ርሃኑም ፡ ከጨረቃ ፡ ሰባት ፣ አጅ ፡ በልጦ ፡ ያበ ል።"),
    (62, 4, "ለቱ ፡ ሁሉ ፡ የፀሐይና ፡ የጨረቃ ፡ መጠና ው ፡ የተካከለ ፡ ነው።"),
    (62, 5, "የዚህን ፡ የፀሐይ ፡ ሥራት ፡ ክየሆ ፡ በኋላ ፣ ሙ ፡ ጨረቃ ፡ የሚባል ፡ የታናዙን ፡ ብርሃን ፣ ፡ ሥራት ፡ አየሁ።"),
    (62, 6, "ብነቱም ፡ እንደ ፡ ሰማይ ፡ ክብ ፡ ነው ፡ በሚቀ Pr ክርስቲያን ሃይማዛ ትና ሥርዓት ክ።"),
    (
        62,
        7,
        "ጽ፪ ፡ ጽር ክፍለ ፡ ብርሃን ፡ እየተቀበለ ፡ ብርሃኑን ፣ ሁሉ ፡ በምሥራቅ ፡ ፈጽሞ ፡ ያገኛል ፡ ሰባት ፡ ሰበት ፡ እጅ ፡ ክፍለ ፡ ብርሃንም ፡ እየተነሣው ፡ ጨለማ ውን ፡ ሁሉ ፡ በምዕራብ ፡ ፈጽሞ ፡ ያገኛል።",
    ),
    (
        62,
        8,
        "በታወቁም ፡ ወራቶች ፡ መግቢያዎቹን ፡ ይለው ጣል ፡ በታወቁም ፡ ወራቶች ፡ አንድ ፡ አንድ ፡ ክፍለ ፡ ብርሃን ፡ አየተሰጠው ፡ መንገዱን ፡ ይሄዳል = በሕፀዐ ፡ በምስቱም ፡ ረኳረቃ ፡ ከፀሐይ ፣ ጋራ ፡ ይገበል ፡ በመካከል ፡ በሉ ፡ በነዚህ ፡ በሁለቱ መስኮቶች ፣ ባራተኛይቱና ፡ በሦስተኛይቱ ፡ መስከት ፡ ሰበት ፡ ቀን ፡ ይወጣል።",
    ),
    (62, 9, "ዳግመኛም ፡ ዙሮ ፡ ተመልፅ ፡ ፀሐይ ፡ በሚወ ጣበት ፣ መስኮት ፡ ይወጣል ፡ በዚያም ፡ መስክኮት፡ ብርሃኑን ፡ ሁሉ ፡ ፈጽሞ ፡ ያገኛል።"),
    (62, 10, "ከፀሐይ ፡ ይርቃል ፡ ፀሐይ ፡ ከሷ ፡ በሚወጣበት፡ በስድስተኛይቱ ፡ መስክት ፡ ስምንት ፡ ቀን ፡ ይገበል።"),
    (62, 11, "ፀሐይም ፡ ክራተኛ ይቱ ፡ መስከት ፡ በወጣ ፡ጊዜ፡ ከምስተኛ ይቱ ፡ መስከት ፡ አስኪወጣ ፡ ድረስ፡ በራተኛይቱ ፡ መስኮት ፡ ሰበት ፡ ቀን፡ ይወጣል።"),
    (62, 12, "ዳግመኛም ፡ ተመልፅ ፡ በራተኛይቱ ፡ መስከኮት፡ ሰበት ፣ ቀን ፣ ይወጣል ፡ ብርሃኑንም ፡ ሁሉ ፈጽሞ ፡ ያገኛል።"),
    (
        62,
        13,
        "ድርቃል በመጀመሪያይቱም ፡ መስከት ፡ ስም ንት ፣ ቀን ፡ ይገበል ፡ ዳግመኛም ፣ ተመልፅ፡ ፀሐይ ፡ ከቧ ፡ በሚወጣበት ፡ በራተኛይቱ ፡ መስክት ፡ ሰበት ፣ ቀን ፡ ይወጣል።",
    ),
    (62, 14, "በየ ወራታቸው ፡ ሥራት ፡ ፀሐይ ፡ አስቀድሞ እንዲወጣ ፡ እአንዲገበ ፡ አናፍራቸውን ፡ አንደ ዚህ ፡ አየሁ ፡ አለ።"),
    (62, 15, "| በነዚያም ፡ ወራቶች ፡ አምስቱ ፡ ዓመት ፡ ይጨ መራል ፡ ለፀሐይም ፡ ሠላሳ ፡ ቀን ፡ ይደርሰዋል።"),
    (
        62,
        16,
        "ላንዱ ፡ ዓመት ፡ ቀኖች ፡ ሁሉ ፡ ይደርሱታል ፡ ከነዚህም ፡ ከምስቱ ፡ ዘመኖች ፡ ተወጣጥተው ቀኖቹ ፡ ሦስት ፡ መቶ ፡ ስሳ ፡ አራት ፡ ቀን ይሆናሉ = ለኮከቦችና ፡ ለፀሐይ ፡ ሰድስት ፡ ቀን ፣ ይደርሳ ቸዋል ፡ ክምስቱ ፡ ዓመት ፡ ስድስት ፣ ስድስት ፡ ቀን ፡ ሆኖ ፡ ሠላሳ ፡ ቀን ፡ ይደርሳቸዋል።",
    ),
    (63, 1, "ጨረቃም ፡ ከከኮከበቦችና ፡ ከፀሐይ ፣ ሠላሳ ፡ ቀን።"),
    (
        63,
        2,
        "ጨረቃም ፡ ዘመኖትን ፡ ጠንቅቁ ፡ ያስቂጥራቹ ዋል 1) ሦስት ፡ መቶ ፡፣ ስላሳ ፡ አራት ፡ቀን ፡ እየሆነ ፡ ጠን ቅቀው ፡ በውነት ፡ ዓመቱን ፡ ይለውጣሉ ፡ አንጂ ሁሉም ፡ ለዘላለሙ ፡ እንደሚኖሩት ፡ መጠን ፡ እንዲት ፡ ቀን ፡ አያተርፉም ፡ አንዲትም ፡ ቀን አያጐሉም ፡ አለ።",
    ),
    (63, 3, "| የሦስቱ ፡ ዓመት ፡ ቀን ፡ ሺህ ፡ ዘጠና ፡ ሁለት።"),
    (63, 4, "ነው ፡ የስምንቱ ፡ ዓመት ፡ ቀኑ ፡ ሁለት ፡ ሸሹ።"),
    (63, 5, "ዘጠኝ ፡ መቶ ፡ አሥራ ፡ ሁለት ፡ ቁን ፡ ይሆን ፡ ዘንድ ፡ ያምስቱ ፡ ዓመት ፡ ቀኑ ፡ ኸሀ ፡ ስምንት ፡ መቶ ፡ሀያ፡ ቀን፡ነው።"),
    (63, 6, "1014 #፣ Ey ተ ክርስቲያን ሃይማ ትና ሥርነት ሮች ፡ ከነሱ ፡ የሚወጡበቸው ፡ የተከፈቱ ፡ አሥሩ ፡ሁለት ፡ መስከቶችን፡እንዲህ፡ አሳየኝ።"),
