    (65, 2, "ሄመሪያ ፡ ያየኋቸው ፡ ሦስቱ ፡ በምሥራቅ ስቱም ፡ በመስፅ ፡ በኋላ ፡ ያየኋቸው ፡ ሦስቱ ፡ አዚብ ፡ ሦስቱ ፡ በምዕራብ ፡ ናቸው።"),
