        65,
        4,
        "ደዘ. ሀም ፡ ዓለም ፡ በተላኩ ፡ ጊዚ ፡ ምድርን ፡ ሉ ፡ ያጠፉታል ፡ በ. ፡ላይ፡ ውኃንም ፡ የጠ ታል ፡ በባ. ፡ ላይ ፡ የሚኖሩትንም ፡ ሁሉ ፡ የብስና ፣ በውኃው ፡ ላይ ፡ ያለውንም ፡ ሁሉ ፡ ጠፋቸዋል።",
