    (65, 12, "እነዚያ ፡ ሁለቱ ፡ ከመስፅ፡ እስክ ፣ በሕር ፡ ድረስ፡ መጥተው ፡ ውህቸውን ፡ ከወደምሥራቅ ፥ በኤ ርትራ ፡ በሕር ፡ ያፈሳሉ።"),
    (66, 1, "| የቀሩቱም ፡ አራቱ ፡ የነሳቸው ፡ በሕር ፡ አስከ ሚሆን ፣ አስከ ፡ ኤርትራ ፡ ባሕር ፣ ድረስ ፡ ደር ሰው ፡ በመስፅ ፡ አጠገብ ፡ ይፈሳሉ።"),
