    (67, 4, "ታላላቆች ፡ ብርሃኖች ፡ አነዚህ ፡ ሁለቱ ፡ ናቸው ፡ ክበባበቸውም ፡ አንደ ፡ ሰማይ ፡ ክበብ ፡ ነው ፡ የሁለቱ ፡ ሁሉ ፡ መጠናቻቸው ፡ የተክከሉ ናቸው።"),
    (67, 5, "| በፀሐይም ፡ ሰሌዳ ፡ ከጨረቃ ፡ ሰባት ፡ ክፍለ ፡ ብርሃን ፡ ይጨመርበታል ፡የፀሐይ ፡ ሰበተኛው፡ ክፍል ፡ አስቲጨረስ፣ ድረስ ፡ በልክ ፡ይቀበላል።"),
    (67, 6, "በምዕራብ ፡ መስኮት ፡ ይገበሉ ፡ ወደ ፡ መስዕ ፡ ይዘራሉ ፡ በሰማይ ፡ ሁነው ፡ አያበሩ ፡ በምሥ ራቅ ፡ መስከት ፡ ይወጣሉ።"),
    (
        67,
        7,
        "| ጨረቃም ፡ በወጣ ፡ ጊዜ ፡ በሰማይ ፡ ይታያል ፡ ነገ፡ በሚቀበለው ፡ ሰባት ፡ በሰባት ፡ ክፍለ ፡ ብር ሃን ፡ ልክ ፡ ዛሬ ፡ ሰበት ፡ ክፍለ ፡ ብርሃን ፡ ይቀ በላል።",
    ),
    (67, 8, "| በሥራ ፣ አራተኛው ፡ ቀን ብርሃኑን ፡ ፈጽሞ ያገኛል ፡ ሦስት ፡ አምስት ፡ ክፍለ ፡ ብርሃንም።"),
    (
        67,
        9,
        "ይጨመርለታል = ) ለዘመን ፡ ምልክት ፡ ሊሆን ፡ አስከ ፡ አሥራ አምስት ፡፣ ቀን ፡ ብርሃኑን ፡ ፈጽሞ ፡ ያገኛል ምስት ፡ አምስት ፡ ክፍለ ፡ ብርሃንም ፡ ይሰጠዋል ጨረቃም ፡ በፀሐይ ፡ ሰበበተኛ ፡ ክፍለ ፡ ብርሃን ያበራል።",
    ),
    (67, 10, "1016 ti 3; et i=) [ey 1) Ll) by] eet ጽ፮።"),
    (
        67,
        11,
        "፡ ተ ካርስቲያን ሃይማዛ ትኝ ሥርዓት በመመሪያው ፡ ዘመን በመይደጀመሪያው፡ መስ ት ፡ በመቶ ፡ ሰበ ፡ ሰባት ፡ ቀን ፡ በመወለጃ ውም ፡ ዘመን ፡ ሦስቱን ፡ ወር ፡ በሠላሳ ፡ በሠላሳ ን ፡ ይታያል ‘ሦስቱንም ፡ ወር፡ በሀያ ፡ዘጠኝ ፡ ሀያ ፡ ዘጠኝ ፡ ቀን ፡ ይታያል።",
    ),
    (
        67,
        12,
        "(ይወለዳል ) ለ ፡ ፀሐይ ፡ ብርሃን ፡ በቀር ፡ ሴላ ፡ ብርሃን ንም ፡ ምን ፡ የላትምና ፡ በሀያ ፡ በሀያ ፡ ቀን ፡ ሊት ፡ ሰው ፡ መስሎ ፡ ቀን ፡ ሰማይ ፡ መስሎ ፡ ታያል።",
    ),
    (
        67,
        13,
        "ሁንም ፡ ልዕ ፡ ማቱሳላ ፡ ሁሉን ፡ አሳየ ሁህ ፡ ሰማይ ፡ ያሉ ፡ የክከከበቦችም ፡ ሥራት ፡ ሁሉ ሪጨረሰ = የቀኑ ፡ ሁሉ ፡ በየዘመኑም ፡ ሁሉ ፡ በየሹመታ ውም ፡ ሁሉ ፡ በያመቱም ፡ ሁሉ ፡ በመግቢያ ም ፡ በታዘዘበትም ፡ ሁሉ ፡ በወሩም ፡ ሁሉ ፡ ሱባዔውም ፡ ሁሉ ፡ የሚሆነውን ፡ የነዚህን ፡ ሥራት ፡ አሳየኝ።",
    ),
    (68, 1, "ዚች ፡ በስድስተኛይቱ ፡ መስከት ፡ ብርሃኑ ፡ ርስሶ ፣ ይጠፋልና ፡ በስድስተኛ ሬቱ ፡ መስከት ሚደረግ ፡ የዜረቃንዎም ፡ ሕፀዕ ፡ አሳየኝ ፡ ለ።"),
    (68, 2, "ዚያም ፡ በኋላ ፡ የወር ፡ መበቻ ፡ ይሆናል ፡ ፀፅ ፣ በሚያደርግበት ፡ ዘመን ፡ በመሄመሪያ ቱ ፡ መስከት ፡ የሚደረገውን • ሕፀፁንም ፡ ሳየኝ።"),
    (68, 3, "ቶ ፡ ሰበ፡ሰበት ፣ ቀን ፡ አስከ.ጨሔጨረስ ፣ ድረስ ሱበዔው፡ቀ.ጥር ፡ ቢቂጠሩት ፡ሀያ ፡ ለምስት፡ በዓ • ከሁለት ፡ ቀን ፡ ይሆናል።"),
    (68, 4, "ጨ ረቃ ፡ በንዱ ፡ ዘመን ፡ ከከኮክቦት ፡ ሥሠሥራትና ፡ ፀሐይ ፡ የሚያንሰው ፣ ጠንቅቁ ፡ ቢቂጥሩት ምስት ፡ ቀን ፡ ይሆናል።"),
    (
        68,
        5,
        "ምታየው ፡ ይሀም ፣ አንቀጽ ፡ በተጨረሰ • ዜ ፡ መሪያቸው ፡ የሚሆን ፡ ገናና ፡ መልአክ ፡ ርኤል ፡ ክሳየኝ ፡ ከብርሃን፡ ሁሉ ፡ የሚበልጥ ንደዚሀ ፡ ያለ ! ሥራ ፡ አንደዚህ ፡ የለ ፡ ምሳሌ ያለህ።",
    ),
    (69, 1, "ዚያም ፡ ወራት ፡ መልጸኩ፡ ሁርኤል ፡ሄና፥ክ ፡ ይ ፡ እነሆ ፣ ሁሉን ፡ አሳየሁህ ፡ ብሉ ፡ መለሰ ኝ።"),
    (69, 2, "ሽንን ፡ ፀሐይ ፡ ይሀንን ፡ ጨረቃ ፡ ታየው ፡ ድ ፡ በበማይ ፡ ያሉ ፡ ከከቦችን ፡ የሚመራ ው ፡ ከዋክብትንም።"),
    (69, 3, "ራቸው ፡ ዘመናቸውንም ፡ የሚለውጡ ፡፣ ከዋክብትንም ፡ ሁሉ ው ፡ ዘንድ ፡ ገለጥሁልህ።"),
    (69, 4, "፡ ክወዕዔቸው- ታያ።"),
    (69, 5, "በኃጥአንም ፡ ወራት ፡ ዘመኖች ፣ ያጥራሉ።"),
    (69, 6, "መሠምሪያቸውና ፡ በርቫቸው ፡ ያለ ፡ ካዝመራ. ው ፡ በ:ኋላ ፡ ይደርሳል።"),
    (69, 7, "ምድር ፡ ላይ ፡ ያለ ፡ ሥራ ፡ ሁሉ ፡ ይለወጣል ፡ ዘመኑም ፣ አፍርቶ ፡ አሬታይም ፡ ዝናምም ፡።"),
    (69, 8, "ለክከላል ፡ ሰማም ፡፣ ዝናምን ፡ አታዘጎንምመም።"),
    (69, 9, "ዚያም ፡ ዘመናች ፡ ፊት ፡ የሚደርሰው ፡ የም ጽyi = Bi een ah Ri ais Ly ime ተ ክርስቲያን ሃይማ ትና ሥርዓት ክ።"),
    (69, 10, "ጽ፮ ፡ ጽሯ፡ በቸው ፡ ዘንድ ፡ ዳግመኛም ፡ አስክታዝላቸው ፡ ድረስ ፡ በልጆችህም ፡ ዘንድ ፡ ጸንድ ፡ ዓመት ፡ አንተውልሃለን ፡ አሉኝ።"),
    (
        69,
        11,
        "በሁለተኛው ፡ ዓመት ፡ ግን ፡ ከነሱ ፡ መክከል ይወስዱሃል ፡ ደጎች ፡ ሰዎች ፡ ለደጎች ፡ ሰዎች አውነት ፡ ነገርን ፡ ያስተምራ ሉና ፡ ለማስተማር ልቡናህ ፡ ይጽና።",
    ),
    (
        69,
        12,
        "ደግ ፡ ሰው ፡ ከደግ ፡ ሰው ፡ ጋራ ፡ደስ፡ ይለዋል አስበሳቸውም ፡ ይዋደዳሉ ፡ ኃጥአም ፡ ሰው፡ ከጋጥ ፡ ሰው ፡ ጋራ ፡ ይሞታል ፡ ወደ ፣ ኃጢአ ትም ፡ የተመለስ ፡ ሰው ፡ ወደ ፡ ኃጢአት ፡ ከተ መለሰው ፡ ሰው ፡ ጋራ ፡ በበሕሪ ፡ ገሃነም ፡ ይሰጥ ማል።",
    ),
    (
        69,
        13,
        "በጎ ፡ ሥራም ፡ የሚሠሩ ፡ ሰዎች ፡ የክፉ ፡ ሰዎ ችን ፡ ሥራ ፡ አንሠራም ፡ ስላሉ ፡ ይሞታሉ ፡እግ ዚአብሔርን ፡ የዘነጉ ፡ የክፉ ፡ ሰዎችንም ሥራ፡ ስለ ፡ ሠሩ ፡ በሚጠፉበት ፡ ቦታ ፡ ይሰበሰበሉ።",
    ),
    (
        69,
        14,
        "በነዚያም ፡ ወራቶች ፡ መላእክት ፡ ክኔ ፡ ጋራ ፡ ተነጋግረው ፡ ጨረሱ ፡ አራቱን ፣ ማዕዘነ፡ዓለም የፈጠረ ፡ ጌታን ፡ አያመሰገንሁት ፡ ወደ ፡ ዝመ ዶቹ ፡ ገበሁ ፡ አለ።",
    ),
    (69, 15, "አሁንም ፡ ልጅ ፡ ማቱሳላ ፡ እነዚህን ፡ ሁሉ ፡ ላንተ ፣ እነግራለሁ ፡ ላንተም ፡ እጽፍልሃለሁ ፡ ሁሉንም ፡ ገለጥሁልህ ፡ አለው።"),
    (
        69,
        16,
        "የነዚህንም ፡ ሁሉ ፡ መጣፎቻቸውን ፡ ሰጠሁህ (አስተማርኩህክ፡) ልጅ ፡ማቱላላ፡ በኔ፡ባባትህ፡ አጅ ፡የተጻፈውን ፡ መጻፍ ፡ ተመልከት ፡ለልጅ፡ ልጅ ፡ ዘመን ፣ አስተምር።",
    ),
    (
        69,
        17,
        "ላንተ ፣፡ጥበብን ፡ አስተማርኩህ ፡ ካንተም፡ በኋላ፡ ለልጆችህ ፡ አስተማርኩ ፡በልቡናቸው፡ ጸንታ፡ ልትኖር ፡ ይችንም ፡ ጥበብ ፡ ለዘላለሙ ፡ አስክ ፣ ልጅ ፡ ልጅ ፡ ዘመን ፡ ድረስ ፡ ለልጆቻቸው ፡ ያስተምሩ ፡ ዘንድ ፡ ላንተ ፡ ልጆች ፡ ለሚሆኑ ህም ፡ ሰዎች ፡ አስተማርሁ።",
    ),
    (
        69,
        18,
        "ይችን ፡ ጥበብ ፡ ይማሯት ፡ ዘንድ ፡ የሚያው ቋት ፡ በጀራቸውም ፡ የሚሰሟት ፡ ሰዎች ፡ በ5 ጢጸት ፣ አይያዙም ፡ ከማሩ ፡ ከተወደዱ ፡ ምግ ቦች ፡ ይልቅ ፡ ለሚማሯት ፡ ሰዎች ፡ ትስማማቹ ዋለች።",
    ),
    (
        69,
        19,
        "ጻድቃንም ፣ ሁሉ ፡ ንዑዳን ፡ ክቡራን ፡ ናቸው በአውነት ፣ ሥራ ፡ ጸንተው ፡ የሚኖሩ ፡ ሰዎች በለ ፡ ዘመናቸውም ፡ ሁሉ ፡ ቍጥር ፡ እንደ ፡ ኃጥአን ፡ ኃጢአት ፡ የሌለባቸውም ፡ ሰዎች ፡ ሁሉ ፡ ንዑዳን ፡ ክቡራን ፡ ናቸው።",
    ),
    (69, 20, "በሰማይ ፡ በሚሔድ ፡ ፀሐይ ፡ በመስክከቱ ፡ ከሸ አለቆች ፡ ጋራ ፡ ሠላሳ ፡ቀን፡ ይገበል ፡ ይወጣል።"),
    (69, 21, "ከሚጨመሩላቸው ፡ አራቱን ፡ ክፍለ ፡ ዘመን።"),
    (69, 22, "ከሚለዩ ፡ ከሚመራቸው ፡ ከራቱ ፡ ከዋክብት ጋራ ፡ የከዋክብት ፣ ሥራታቸው ፡ ይህ ፡ ነው።"),
