    (69, 26, "- ስሙ ፣ ተመዓኒ ፡ ( ውፁይ ፡) ፀሐሬንም ፡ የሚ በል ፡ ምልክኤል ፡ የሚባል ፡ ከክብ ፡ በመጀመ ሪቱሃው ፡ ዘመን ፡ ወጥቶ ፡ ይመግበል።"),
