        71,
        15,
        "አውነትን ፡ የቀና ፡ ሥራንም ፡ የሚሠሩ ፡ የኖ ኅን ፡ ወገኖች ፡ግን ፡ ለዘላለሙ ፡ ሕግ ፡ ሊጠብቁ አታጥፋ ፡ ከኔ ፡ ከበሪያህም ፡ ልመና ፡ አቤቱ ፡ ፊትህን ፡ አትመልስ ፡ አልኩት ፡ አለ።",
