    (72, 10, "| ቫበቱ ፡ ሰዎችን ፡ የመሰሉ ፡ መላእክት ፡ አነሆ፡ ሰማይ ፡ ወጡ ፡ አንዱ ፡ ከዚያ ፡ ቦታ ፡ ወጣ ስቱም ፣ ከሱ ፡ ጋር ፡ ወጡ።"),
