    (72, 12, "በረጅም ፡ ተራራ ፡ ላይ ፡ ከፍ ፣ አድርገው ፡ ዚህ ፡ ዓለም ፡ የምትበልጥ ፡ ገነትን ፡ አሳዩኝ ፡ ረብታውም ፣ ሁሉ ፡ ከሱ ፡ ያነሰ ፡ ሆነ።"),
