    (72, 14, "ጁን ፡ አግሩን ፡ አሥሮ ፡ በጥልቅ ፡ ጉድጓድ ለው ፡ ያም ፡ ጉድጓድ ፡ ጠበብ ፡ ነው ፡ ጥልቅ ፡ ጭንቅ ፡ ነው ፡ ጨለማም ፡ ነው።"),
