    (72, 19, "ዚህም ፣ ካራቱ ፡ መላአክት ፡ አንዱ ፣፡ሱርያል፡ ምርሮ ፣ ወዳለው ፡ ወዴ ፣ ኖኅ ፡ ጌይ ፡ ኖኅም ፡ ራደ፡እየ ተንቀጠቀጠ ፡የማየ ፡አይህን፡፣ ምሥ ፣ ጸስተማረ።"),
    (72, 20, "ስ ፡ በለ ፡ አአምሮም ፡ሆነ ፡ ታላቃ ፡ መርክ ም ፡ ሠርቶ ፡ በ9. ፡ ተቀመጠ።"),
