    (
        79,
        3,
        "ምሰሰዎቹም ሁሉ ፡ አዲሶች ናቸው ፡ ጌጢ.ም፡ ሁሉ ፡ አዲስ ፡ ነወ: ፡ ቀድሞ ፡ አርጅታ ፡ ክፈረሳ ትም ፣ ቤት ፡ ይልቅ ፣ ታላቅ ፡ ነው ፡ ሐዋርያትም ፡ ሁሉ ፡ በመክከዕ. • ናቸው።",
    ),
    (79, 4, 'ከሞት" ፡ የቀሩ ፡ አስራኤልንዎም ፡ ሁሉ ፡ አየኋ ቸው ፡ በዚ.ሀ፡ዓለም ፡ የቀሩም፡፣ሁሉ ፡ ከሰማይ ፡ በታች ፡ ያሉ ፡ አሕዛብም ፡ ሁሉ።'),
    (79, 5, "ኒሀ ፡ ለሐዋርያት ፡ ወድቀው ፡ ይሰግዳሉ ፡ ይለ ምፈቸዋል ፡ የነገሯቸው ንም ፡ ሁሉ ፡ ቃል ፡ ፎሰ መ-ዋቹዋል።"),
    (79, 6, "ከዚህም ፡ በኋላ ፡ ነጭ ፡ ልብስ ፡ የለበሱ ፡ አስቀ ድመውም ፡ ወደ ፡ሰማይ ፡ ያወጠኝ ፣ እነዚሀም ስቱ ፡ መላእክት ፡ አጅን ፡ ያዙኝ።"),
    (
        80,
        1,
        "የዚያም ፡ የክርስቶስ ፡ ሥልጣኑ ' ይዛኝ ፡ ሳለች ያ: ፡ ሳትደረግ ፡ አውጥተው ፡ በኒህ ፣ በሐዋ ያት ፡ መክከል ፡ አኖናሩኝ = ነዚያም • ሐዋርያት ፡ ሁሉ ፡ በለ ፡ አአምር ኑ ፡ ጸጋ ፡ ክብራቸውም ፣ ታላቅ ፡ ሆነ ፡ ከነቀ ም ፡የነፃ፡ሆነ።",
    ),
    (80, 2, "ጠፉ ፡ የተበተኑ ፡ ሁሉ ፡ በሩቅ ፡ ያሉ ፡ አሳዛ ም ፡ ሁሉ ፡ በአ.የሩሳሌም ፡ የነበሩ • እስራኤ ም ፡ ሁሉ ፡በዚ.ህ፡ ቤተ ፣መቅዶስ ፡ ተሰበሰቡ።"),
    (80, 3, "ሉም ፡ ዶጋግሣ ፣ ሁነዋልና ፡ ወደ ፡ ማደሪያው ፡ ተ ፡ መቅደስም ፡ ተመልሰዋልና፣፡ የአስራኤል ዥ • እግዚአብሔርም ፣ ታላቅ ፡ ዶስታ ፡ ደስ ፡ ለው።"),
    (80, 4, "ሐዋርያት ፡የተሰጣቸወው፡ይሀንንም፡ሥልጣን፡ 1፻ጽ tie 8ጽ፣ iy RR [iy ክርስቲያን ሃይማነ ትና ሥርንት።"),
