    (82, 5, "ኖክም ፡ ከመጻሕፍት አየጠቀሰ ' ይናገር ፡ መረ ፡ በለአእአምሮ የምሆን • እኔ ፡ ሄኖክ ፡ በመጀመሪያይቱ ፡ሱበዔ ፡ ተወለድሁ።"),
