    (82, 11, "መጨረቫዛዋም ፡ የመንግሥቱ 'ቤት ፡ በአሳት ፡ ይቃጠላል ፡ የተመረጡ ፡ የመንግሥትም! ዘመ ች ፡ ሁሉ ፡በባ ፡ይበተናሉ።"),
    (82, 12, "ዚህም ፡ በኋላ ፡ በሰበተኛዴይቲ ፡ ሱበዔ ፡ ወንጀ ፡ ኃጠ.አሂ ፡ ብዙ ፡ የሆነ ፣ ሥራዋም ፣ ሁሉ! ንጀል ፡ የሆን ፡ ልጅ ፡ ትነሣለች።"),
