        "ከሥር ፡ ከመሠረታቸው ፡ ሁሉ ፡ ይጠፋሉና ፡ በሰይፍም ፡ ተቀራደው ፡ የል ቃሉና ፡ ወርቅን ብርንም ፣ የሚሰበስቧት ፡ ሰዎች ፡ ፍርዱ ፡ ፈጥ ነው ፡ ይጠፋሉና ፡ የሰው ፡ ገንዘብ ፡ ቀምተው ቤታቸውን ፡ ለሚሠሩ ፡ ሰዎች ፡ ወዮላቸው።",
