        83,
        11,
        "በውነት ፡ ያይደለ ፣ ወርቅና • ብርን ፡ የምትሰበ ስቡ ፡ በለጸግነትን ፡ አገኘን ፡ ገንዘቡም በዛልን ፡ የወደድነውንም ፡ሁሉ ፡ገዛን፡የምትሉ፡ሰዎች፡ ለናንተ ፡ ወዮላችሁ።",
