    (84, 2, "ከናንተ ፡ ፈጥኖ ፣ ይጠፋል ፡ አንጂ ፡ በለጠግነት፡ አይናኖርላችሁምና ፡ አሰታችሁ ፡ እንደ • ውህ • ይበዛል።"),
