        85,
        5,
        "ኃጥአን ፡ ተራ.ሪ.ው ፡ በባሕርዩ፣ተፐዥ' ፡ አንዳል ነበረ፡አንግዲህም ፣ ወ5.ሀ ፡፣ አንዳይሆን ፡ ኮረብ ታይቱ ፡ ለት ፡ ሰት ፡ በሪያ ፣ እንዳይደሉ ፡ ለናንተ ፡ ነገርኋችሁ።",
