    (88, 3, "በነዚያም ፡ ወራቶች ፡ የጥበብን ፡ ነገር ፡ የሚቀ በሉ ፡የሚወዷትም ፡ ሰዎች ፡ ሁሉ ፡ የተደነቁ፣ ሰዎች ፡ናቸው።"),
    (89, 1, "1033 ይ! [1 =) ክርስቲያን ሃይማኝትና ሥርዓት ክ።"),
    (89, 2, "a፳ ፡ 8 ቢተኙም ፡ ብዙ ፡ አንቅልፍን ፡ ይተኛሉ ፡ የሚ ፈሩትም ፡ ነገር ፡ የላቸውም።"),
